export function computeStateHash(data: unknown): string {
  const json = typeof data === "string" ? data : canonicalJson(data);
  return sha256Bytes(new TextEncoder().encode(json));
}

// ── Capture ──────────────────────────────────────────────────────────────

/** Milliseconds of wall clock a trace attributes to one simulation tick. */
const MS_PER_TICK = 3000;

export interface TraceCaptureOptions {
  /** Defaults to the run's own `episode.id`. */
  episodeId?: string;
  /**
   * The one run this trace came from. Left off when the caller has no session
   * id to quote; see `RestaurantArenaTraceV3.sessionId`.
   */
  sessionId?: string;
  /** Required: live gameplay, synthetic episodes and benchmark episodes must stay distinguishable. */
  runKind: "live" | "synthetic" | "benchmark";
  /** Defaults to the arena build this module was published with. */
  envVersion?: string;
  /**
   * Wall clock for tick 0. Supplied by deterministic exporters so the same
   * seed produces the same bytes; the run's own clock is used when omitted.
   */
  startTime?: string;
  deletion?: Partial<TraceV3Deletion>;
  /** Omit to capture the run's own recorded event journal; pass to replace it wholesale. */
  events?: TraceV3Event[];
  /**
   * Events the caller wants merged into the captured journal alongside the
   * game's own recorded events (e.g. an out-of-band player note). Each one is
   * stamped with the round its `tick` falls in — round *r* covers ticks 2r-1
   * and 2r, tick 0 is round 1 — and merged in tick order, after any recorded
   * event on the same tick.
   */
  additionalEvents?: TraceV3Event[];
}

const RUN_KINDS: readonly TraceCaptureOptions["runKind"][] = ["live", "synthetic", "benchmark"];

/**
 * Re-stamp a journal onto a caller-supplied tick-0 wall clock. The engine
 * derives every event timestamp from `startTime + tick * 3s`, so an exporter
 * that wants byte-stable output only has to name tick 0.
 */
function restampEvents(events: TraceV3Event[], startMs: number): TraceV3Event[] {
  return events.map((event) => ({
    ...event,
    timestamp: new Date(startMs + event.tick * MS_PER_TICK).toISOString(),
  }));
}

/**
 * Fold caller-supplied events into the recorded journal in tick order,
 * stamping each with the round its tick belongs to. Ties keep the recorded
 * event first: the journal is the run's own account, the extras annotate it.
 */
function mergeAdditionalEvents(
  recorded: TraceV3Event[],
  additional: TraceV3Event[],
  ticksPerRound: number,
): TraceV3Event[] {
  const stamped = additional.map((event) => ({ ...event, round: roundForTick(event.tick, ticksPerRound) }));
  return [...recorded, ...stamped]
    .map((event, order) => ({ event, order }))
    .sort((a, b) => a.event.tick - b.event.tick || a.order - b.order)
    .map(({ event }) => event);
}

/**
 * Turn a running game into a complete restaurant-arena-trace-v3 record: the
 * world at tick 0, the event journal, the ordered replay inputs with their
 * checkpoint hashes, and the terminal record as the engine reports it.
 *
 * `RestaurantGame.captureTrace` is the instance-method form of this and
 * delegates straight here, so a caller can use either.
 */
export function captureArenaTrace(
  game: RestaurantGame,
  options: TraceCaptureOptions,
): RestaurantArenaTraceV3 {
  if (options === null || typeof options !== "object") {
    throw new TypeError("captureArenaTrace requires capture options naming a runKind");
  }
  if (!RUN_KINDS.includes(options.runKind)) {
    throw new TypeError(
      `captureArenaTrace requires runKind of ${RUN_KINDS.join(", ")}; got ${JSON.stringify(options.runKind)}`,
    );
  }
  if (options.startTime !== undefined && Number.isNaN(Date.parse(options.startTime))) {
    throw new TypeError(`captureArenaTrace startTime is not a date-time: ${JSON.stringify(options.startTime)}`);
  }

  const state = game.state();
  const initialState = game.getInitialState();
  const seed = typeof initialState.seed === "number" ? initialState.seed : state.seed;
  const recorded =
    options.events ??
    (options.startTime === undefined
      ? game.getRecordedEvents()
      : restampEvents(game.getRecordedEvents(), Date.parse(options.startTime)));
  const events = options.additionalEvents?.length
    ? mergeAdditionalEvents(recorded, options.additionalEvents, game.contract().ticksPerRound)
    : recorded;

  return {
    version: TRACE_V3_VERSION,
    episodeId: options.episodeId ?? state.episode.id ?? `dinner-rush-${seed}`,
    ...(options.sessionId === undefined ? {} : { sessionId: options.sessionId }),
    seed,
    envVersion: options.envVersion ?? ARENA_ENV_VERSION,
    contractVersion: TRACE_V3_CONTRACT_VERSION,
    runKind: options.runKind,
    initialState,
    events,
    replay: game.getReplayRecord(),
    terminal: game.getTerminalStatus(),
    deletion: {
      requestId: options.deletion?.requestId ?? null,
      status: options.deletion?.status ?? "retained",
    },
  };
}

// ── Export ───────────────────────────────────────────────────────────────

/**
 * The whole record as one pretty-printed JSON document, in field order and
 * with the backend's decimal spelling for float fields, so a re-export of an
 * unchanged run is byte-identical to the file already on disk.
 */
export function exportTraceJson(trace: RestaurantArenaTraceV3): string {
  return `${serializeJson(trace, true, false) ?? "null"}\n`;
}

/**
 * The streaming form: a header line carrying everything but the journal,
 * then one line per event in recorded order.
 */
export function exportTraceJsonl(trace: RestaurantArenaTraceV3): string {
  const { events, ...header } = trace;
  return `${[JSON.stringify(header), ...events.map((event) => JSON.stringify(event))].join("\n")}\n`;
}

/** Re-join a JSONL export into the record `exportTraceJsonl` was given. */
export function parseTraceJsonl(text: string): RestaurantArenaTraceV3 {
  const lines = text.split("\n").filter((line) => line.trim().length > 0);
  const [header, ...eventLines] = lines;
  if (header === undefined) throw new Error("trace JSONL is empty: no header line");
  const parsed = JSON.parse(header) as Record<string, unknown>;
  const events = eventLines.map((line) => JSON.parse(line) as TraceV3Event);
  // Restore the recorded field order, so a JSONL round trip re-exports as JSON
  // identically: `events` sits between `initialState` and `replay`.
  const { replay, terminal, deletion, ...head } = parsed;
  return { ...head, events, replay, terminal, deletion } as unknown as RestaurantArenaTraceV3;
}

// ── Validation ───────────────────────────────────────────────────────────

export interface TraceValidationResult {
  valid: boolean;
  errors: string[];
}

const ARENA_ID = /^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$/;
const IDEMPOTENCY_KEY = /^[A-Za-z0-9][A-Za-z0-9._:-]{0,129}$/;
const STATE_HASH = /^sha256:[0-9a-f]{64}$/;
const DATE_TIME = /^\d{4}-\d{2}-\d{2}[Tt]\d{2}:\d{2}:\d{2}(\.\d+)?([Zz]|[+-]\d{2}:\d{2})$/;

const TRACE_ROLES = ["host", "supply_lead", "chef", "server", "expediter"] as const;
const TRACE_EVENT_KINDS: readonly TraceEventKind[] = [
  "observation", "action", "player_correction", "message", "outcome", "inspection",
  "hold", "hold_cleared", "verification_request", "verification_response",
  "escalation", "handoff", "supply_order", "supply_delivered", "stockout",
];
const REPLAY_VARIATIONS = ["tutorial-shift", "dinner-rush", "quiet-tuesday", "saturday-night"] as const;
const ACTION_TOOLS = [
  "inspect", "prepare", "serve", "seat", "update_guest",
  "coordinate", "request_help", "send_message", "approve", "correct",
] as const;

/**
 * One record's worth of field-by-field complaints. Every check names the path
 * it failed on, because "invalid trace" tells a caller holding a 400-event
 * export nothing about which field to look at.
 */
class FieldChecker {
  readonly errors: string[] = [];

  fail(path: string, expected: string): false {
    this.errors.push(`${path || "record"}: ${expected}`);
    return false;
  }

  /** An object with no keys beyond `allowed` and none of `required` missing. */
  object(
    path: string,
    value: unknown,
    required: readonly string[],
    allowed: readonly string[],
  ): value is Record<string, unknown> {
    if (typeof value !== "object" || value === null || Array.isArray(value)) {
      return this.fail(path, "expected an object");
    }
    const record = value as Record<string, unknown>;
    const child = (key: string) => (path ? `${path}.${key}` : key);
    let ok = true;
    for (const key of required) {
      if (record[key] === undefined) ok = this.fail(child(key), "is required");
    }
    for (const key of Object.keys(record)) {
      if (!allowed.includes(key)) ok = this.fail(child(key), "is not a known field");
    }
    return ok;
  }

  array(path: string, value: unknown): value is unknown[] {
    return Array.isArray(value) ? true : this.fail(path, "expected an array");
  }

  const(path: string, value: unknown, expected: string): boolean {
    return value === expected ? true : this.fail(path, `expected ${JSON.stringify(expected)}`);
  }

  enum<T extends string>(path: string, value: unknown, allowed: readonly T[]): boolean {
    return allowed.includes(value as T) ? true : this.fail(path, `expected one of ${allowed.join(", ")}`);
  }

  string(path: string, value: unknown, minLength = 0): boolean {
    if (typeof value !== "string") return this.fail(path, "expected a string");
    return value.length >= minLength ? true : this.fail(path, `expected at least ${minLength} character(s)`);
  }

  pattern(path: string, value: unknown, re: RegExp, described: string): boolean {
    if (typeof value !== "string") return this.fail(path, "expected a string");
    return re.test(value) ? true : this.fail(path, `expected ${described}`);
  }

  integer(path: string, value: unknown, min?: number, max?: number): boolean {
    if (typeof value !== "number" || !Number.isInteger(value)) return this.fail(path, "expected an integer");
    if (min !== undefined && value < min) return this.fail(path, `expected an integer >= ${min}`);
    if (max !== undefined && value > max) return this.fail(path, `expected an integer <= ${max}`);
    return true;
  }

  number(path: string, value: unknown, min?: number, max?: number): boolean {
    if (typeof value !== "number" || !Number.isFinite(value)) return this.fail(path, "expected a number");
    if (min !== undefined && value < min) return this.fail(path, `expected a number >= ${min}`);
    if (max !== undefined && value > max) return this.fail(path, `expected a number <= ${max}`);
    return true;
  }

  boolean(path: string, value: unknown): boolean {
    return typeof value === "boolean" ? true : this.fail(path, "expected a boolean");
  }

  /** A nullable free-form object, as the payload-shaped event fields are. */
  nullableObject(path: string, value: unknown): boolean {
    if (value === null) return true;
    if (typeof value !== "object" || Array.isArray(value)) return this.fail(path, "expected an object or null");
    return true;
  }

  nullableString(path: string, value: unknown): boolean {
    if (value === null) return true;
    return typeof value === "string" ? true : this.fail(path, "expected a string or null");
  }

  dateTime(path: string, value: unknown): boolean {
    if (!this.pattern(path, value, DATE_TIME, "an RFC 3339 date-time")) return false;
    return Number.isNaN(Date.parse(value as string)) ? this.fail(path, "expected a parsable date-time") : true;
  }

  arenaId(path: string, value: unknown): boolean {
    return this.pattern(path, value, ARENA_ID, "an arena id (alphanumeric start, then [A-Za-z0-9._-], max 64)");
  }

  stateHash(path: string, value: unknown): boolean {
    return this.pattern(path, value, STATE_HASH, "a sha256: hash of 64 lowercase hex digits");
  }
}

const STATE_TOP_LEVEL = [
  "version", "seed", "episode", "clock", "tables", "orders", "inventory",
  "equipment", "workers", "emergency", "reputation", "outcomes",
] as const;

/** `restaurant-arena-state-v1`, checked field by field. */
function checkArenaStateV1(check: FieldChecker, path: string, value: unknown): void {
  const required = STATE_TOP_LEVEL.filter((key) => key !== "emergency");
  if (!check.object(path, value, required, STATE_TOP_LEVEL)) return;
  const state = value as Record<string, unknown>;

  check.const(`${path}.version`, state.version, "restaurant-arena/v1");
  check.integer(`${path}.seed`, state.seed, 0);

  const episodeFields = ["id", "phase", "tick", "maxTicks"] as const;
  if (check.object(`${path}.episode`, state.episode, episodeFields, episodeFields)) {
    const episode = state.episode as Record<string, unknown>;
    check.arenaId(`${path}.episode.id`, episode.id);
    check.enum(`${path}.episode.phase`, episode.phase, ["active", "complete"]);
    check.integer(`${path}.episode.tick`, episode.tick, 0);
    check.integer(`${path}.episode.maxTicks`, episode.maxTicks, 1);
  }

  if (check.object(`${path}.clock`, state.clock, ["minute", "speed"], ["minute", "speed"])) {
    const clock = state.clock as Record<string, unknown>;
    check.integer(`${path}.clock.minute`, clock.minute, 0);
    check.integer(`${path}.clock.speed`, clock.speed, 1);
  }

  if (check.array(`${path}.tables`, state.tables)) {
    (state.tables as unknown[]).forEach((table, index) => {
      const at = `${path}.tables[${index}]`;
      if (!check.object(at, table, ["id", "seats", "status"], ["id", "seats", "status", "orderId"])) return;
      const row = table as Record<string, unknown>;
      check.arenaId(`${at}.id`, row.id);
      check.integer(`${at}.seats`, row.seats, 1);
      check.enum(`${at}.status`, row.status, ["empty", "occupied"]);
      if (row.orderId !== undefined) check.arenaId(`${at}.orderId`, row.orderId);
    });
  }

  if (check.array(`${path}.orders`, state.orders)) {
    (state.orders as unknown[]).forEach((order, index) => {
      const at = `${path}.orders[${index}]`;
      const allowed = ["id", "tableId", "items", "status", "allergy", "priority"];
      if (!check.object(at, order, ["id", "items", "status", "priority"], allowed)) return;
      const row = order as Record<string, unknown>;
      check.arenaId(`${at}.id`, row.id);
      if (row.tableId !== undefined) check.arenaId(`${at}.tableId`, row.tableId);
      if (check.array(`${at}.items`, row.items)) {
        (row.items as unknown[]).forEach((item, itemIndex) => check.string(`${at}.items[${itemIndex}]`, item, 1));
      }
      check.enum(`${at}.status`, row.status, ["queued", "seated", "preparing", "ready", "served", "cancelled"]);
      if (row.allergy !== undefined) check.string(`${at}.allergy`, row.allergy, 1);
      check.enum(`${at}.priority`, row.priority, ["normal", "high"]);
    });
  }

  if (typeof state.inventory !== "object" || state.inventory === null || Array.isArray(state.inventory)) {
    check.fail(`${path}.inventory`, "expected an object");
  } else {
    for (const [item, count] of Object.entries(state.inventory as Record<string, unknown>)) {
      check.integer(`${path}.inventory.${item}`, count, 0);
    }
  }

  if (check.array(`${path}.equipment`, state.equipment)) {
    (state.equipment as unknown[]).forEach((item, index) => {
      const at = `${path}.equipment[${index}]`;
      const allowed = ["id", "kind", "status", "safetyThreshold", "reading"];
      if (!check.object(at, item, ["id", "kind", "status"], allowed)) return;
      const row = item as Record<string, unknown>;
      check.arenaId(`${at}.id`, row.id);
      check.enum(`${at}.kind`, row.kind, ["oven", "warming_shelf"]);
      check.enum(`${at}.status`, row.status, ["working", "failed", "degraded"]);
      if (row.safetyThreshold !== undefined) check.number(`${at}.safetyThreshold`, row.safetyThreshold);
      if (row.reading !== undefined) check.number(`${at}.reading`, row.reading);
    });
  }

  if (check.array(`${path}.workers`, state.workers)) {
    (state.workers as unknown[]).forEach((worker, index) => {
      const at = `${path}.workers[${index}]`;
      const allowed = ["id", "role", "load", "location", "lastAction"];
      if (!check.object(at, worker, ["id", "role", "load", "location"], allowed)) return;
      const row = worker as Record<string, unknown>;
      check.arenaId(`${at}.id`, row.id);
      check.enum(`${at}.role`, row.role, TRACE_ROLES);
      check.number(`${at}.load`, row.load, 0, 1);
      check.enum(`${at}.location`, row.location, ["floor", "kitchen", "pass", "queue"]);
      if (row.lastAction !== undefined) check.string(`${at}.lastAction`, row.lastAction);
    });
  }

  const emergencyFields = ["kind", "active", "startedAt"] as const;
  if (state.emergency !== undefined && check.object(`${path}.emergency`, state.emergency, emergencyFields, emergencyFields)) {
    const emergency = state.emergency as Record<string, unknown>;
    check.const(`${path}.emergency.kind`, emergency.kind, "oven_failure");
    check.boolean(`${path}.emergency.active`, emergency.active);
    check.integer(`${path}.emergency.startedAt`, emergency.startedAt, 0);
  }

  check.number(`${path}.reputation`, state.reputation, 0, 100);

  const outcomeKeys = [
    "cash", "satisfaction", "waste", "waitTime",
    "completed", "safeOrders", "coordination", "correctionUptake",
  ] as const;
  if (check.object(`${path}.outcomes`, state.outcomes, outcomeKeys, outcomeKeys)) {
    const outcomes = state.outcomes as Record<string, unknown>;
    check.number(`${path}.outcomes.cash`, outcomes.cash, 0);
    check.number(`${path}.outcomes.satisfaction`, outcomes.satisfaction, 0, 1);
    check.number(`${path}.outcomes.waste`, outcomes.waste, 0);
    check.number(`${path}.outcomes.waitTime`, outcomes.waitTime, 0);
    check.integer(`${path}.outcomes.completed`, outcomes.completed, 0);
    check.integer(`${path}.outcomes.safeOrders`, outcomes.safeOrders, 0);
    check.number(`${path}.outcomes.coordination`, outcomes.coordination, 0, 1);
    check.number(`${path}.outcomes.correctionUptake`, outcomes.correctionUptake, 0, 1);
  }
}

const EVENT_FIELDS = [
  "tick", "round", "kind", "timestamp", "stateHash", "actorId", "role", "targetRole",
  "checkpointId", "model", "requestId", "idempotencyKey", "text", "observation",
  "action", "toolResult", "outcome", "correctionRationale", "correctionCategory",
  "changedDecisionEventId", "probeEventId", "subject", "payload",
] as const;

function checkTraceEvent(check: FieldChecker, path: string, value: unknown): void {
  if (!check.object(path, value, ["tick", "kind", "timestamp", "stateHash"], EVENT_FIELDS)) return;
  const event = value as Record<string, unknown>;

  check.integer(`${path}.tick`, event.tick, 0);
  check.enum(`${path}.kind`, event.kind, TRACE_EVENT_KINDS);
  check.dateTime(`${path}.timestamp`, event.timestamp);
  check.stateHash(`${path}.stateHash`, event.stateHash);
  if (event.round !== undefined) check.integer(`${path}.round`, event.round, 1);
  if (event.actorId !== undefined) check.arenaId(`${path}.actorId`, event.actorId);
  if (event.role !== undefined) check.enum(`${path}.role`, event.role, TRACE_ROLES);
  if (event.targetRole !== undefined) check.enum(`${path}.targetRole`, event.targetRole, TRACE_ROLES);
  if (event.checkpointId !== undefined) check.arenaId(`${path}.checkpointId`, event.checkpointId);
  if (event.requestId !== undefined) check.arenaId(`${path}.requestId`, event.requestId);
  if (event.idempotencyKey !== undefined) {
    check.pattern(
      `${path}.idempotencyKey`,
      event.idempotencyKey,
      IDEMPOTENCY_KEY,
      "an idempotency key of up to 130 [A-Za-z0-9._:-] characters",
    );
  }
  if (event.text !== undefined) check.nullableString(`${path}.text`, event.text);
  if (event.observation !== undefined) check.nullableObject(`${path}.observation`, event.observation);
  if (event.action !== undefined) check.nullableObject(`${path}.action`, event.action);
  if (event.outcome !== undefined) check.nullableObject(`${path}.outcome`, event.outcome);
  if (event.payload !== undefined) check.nullableObject(`${path}.payload`, event.payload);
  if (event.correctionRationale !== undefined) check.nullableString(`${path}.correctionRationale`, event.correctionRationale);
  if (event.correctionCategory !== undefined && event.correctionCategory !== null) {
    check.enum(`${path}.correctionCategory`, event.correctionCategory, ["safety", "priority", "quality", "pace"]);
  }
  for (const key of ["changedDecisionEventId", "probeEventId"] as const) {
    if (event[key] !== undefined && event[key] !== null) check.arenaId(`${path}.${key}`, event[key]);
  }

  const modelFields = ["provider", "name", "version"] as const;
  if (event.model !== undefined && check.object(`${path}.model`, event.model, ["provider", "name"], modelFields)) {
    const model = event.model as Record<string, unknown>;
    check.string(`${path}.model.provider`, model.provider, 1);
    check.string(`${path}.model.name`, model.name, 1);
    if (model.version !== undefined) check.string(`${path}.model.version`, model.version, 1);
  }

  if (event.subject !== undefined && check.object(`${path}.subject`, event.subject, ["kind", "id"], ["kind", "id"])) {
    const subject = event.subject as Record<string, unknown>;
    check.enum(`${path}.subject.kind`, subject.kind, ["order", "ingredient", "equipment", "handoff"]);
    check.arenaId(`${path}.subject.id`, subject.id);
  }

  if (event.toolResult !== undefined && event.toolResult !== null) {
    checkToolResult(check, `${path}.toolResult`, event.toolResult);
  }
}

/** The three reserved keys a grader sorts on, and the ok/error agreement between them. */
function checkToolResult(check: FieldChecker, path: string, value: unknown): void {
  if (typeof value !== "object" || value === null || Array.isArray(value)) {
    check.fail(path, "expected an object or null");
    return;
  }
  const result = value as Record<string, unknown>;
  if (result.ok !== undefined) check.boolean(`${path}.ok`, result.ok);
  if (result.latencyMs !== undefined) check.number(`${path}.latencyMs`, result.latencyMs, 0);
  if (result.error === undefined || result.error === null) {
    if (result.ok === false) check.fail(`${path}.error`, "is required when ok is false");
    return;
  }
  const errorFields = ["code", "message", "retryable"] as const;
  if (check.object(`${path}.error`, result.error, ["code", "message"], errorFields)) {
    const error = result.error as Record<string, unknown>;
    check.string(`${path}.error.code`, error.code, 1);
    check.string(`${path}.error.message`, error.message, 1);
    if (error.retryable !== undefined) check.boolean(`${path}.error.retryable`, error.retryable);
  }
  // A consumer filtering on `ok` and one filtering on error presence must not
  // disagree about the same event.
  if (result.ok !== false) check.fail(`${path}.ok`, "expected false, because an error body means the call failed");
}

function checkActionEnvelopeV1(check: FieldChecker, path: string, value: unknown): void {
  const fields = [
    "version", "episodeId", "actorId", "actorType", "role", "tool",
    "arguments", "tick", "timestamp", "requestId", "idempotencyKey",
  ] as const;
  if (!check.object(path, value, fields, fields)) return;
  const envelope = value as Record<string, unknown>;
  check.const(`${path}.version`, envelope.version, "restaurant-arena-action/v1");
  check.arenaId(`${path}.episodeId`, envelope.episodeId);
  check.arenaId(`${path}.actorId`, envelope.actorId);
  check.enum(`${path}.actorType`, envelope.actorType, ["worker", "player"]);
  check.enum(`${path}.role`, envelope.role, TRACE_ROLES);
  check.enum(`${path}.tool`, envelope.tool, ACTION_TOOLS);
  if (typeof envelope.arguments !== "object" || envelope.arguments === null || Array.isArray(envelope.arguments)) {
    check.fail(`${path}.arguments`, "expected an object");
  }
  check.integer(`${path}.tick`, envelope.tick, 0);
  check.dateTime(`${path}.timestamp`, envelope.timestamp);
  check.arenaId(`${path}.requestId`, envelope.requestId);
  check.pattern(
    `${path}.idempotencyKey`,
    envelope.idempotencyKey,
    IDEMPOTENCY_KEY,
    "an idempotency key of up to 130 [A-Za-z0-9._:-] characters",
  );
}

const HASH_FIELDS = ["kind", "tick", "stateHash", "restaurantStateHash"] as const;
const INPUT_SHAPES = {
  step: { required: ["kind", "tick", "stateHash", "action"], allowed: [...HASH_FIELDS, "action"] },
  time: { required: ["kind", "tick", "stateHash"], allowed: [...HASH_FIELDS] },
  envelope: { required: ["kind", "tick", "stateHash", "envelope"], allowed: [...HASH_FIELDS, "envelope", "telemetry"] },
  controllers: { required: ["kind", "tick", "stateHash", "roles"], allowed: [...HASH_FIELDS, "roles"] },
} as const;

function checkReplayInput(check: FieldChecker, path: string, value: unknown): void {
  if (typeof value !== "object" || value === null || Array.isArray(value)) {
    check.fail(path, "expected an object");
    return;
  }
  const input = value as Record<string, unknown>;
  const kind = input.kind as keyof typeof INPUT_SHAPES;
  if (typeof kind !== "string" || !Object.hasOwn(INPUT_SHAPES, kind)) {
    check.fail(`${path}.kind`, `expected one of ${Object.keys(INPUT_SHAPES).join(", ")}`);
    return;
  }
  const shape = INPUT_SHAPES[kind];
  if (!check.object(path, input, shape.required, shape.allowed)) return;

  check.integer(`${path}.tick`, input.tick, 0);
  check.stateHash(`${path}.stateHash`, input.stateHash);
  if (input.restaurantStateHash !== undefined) check.stateHash(`${path}.restaurantStateHash`, input.restaurantStateHash);

  if (kind === "step") check.string(`${path}.action`, input.action, 1);
  if (kind === "envelope") {
    checkActionEnvelopeV1(check, `${path}.envelope`, input.envelope);
    const telemetry = input.telemetry;
    if (telemetry !== undefined && (typeof telemetry !== "object" || telemetry === null || Array.isArray(telemetry))) {
      check.fail(`${path}.telemetry`, "expected an object");
    }
  }
  if (kind === "controllers" && check.array(`${path}.roles`, input.roles)) {
    const roles = input.roles as unknown[];
    roles.forEach((role, index) => check.enum(`${path}.roles[${index}]`, role, TRACE_ROLES));
    if (new Set(roles).size !== roles.length) check.fail(`${path}.roles`, "expected unique roles");
  }
}

const TRACE_TOP_LEVEL = [
  "version", "episodeId", "sessionId", "seed", "envVersion", "contractVersion",
  "runKind", "initialState", "events", "replay", "terminal", "deletion",
] as const;

const TRACE_REQUIRED = TRACE_TOP_LEVEL.filter((key) => key !== "sessionId");

/**
 * Validate a candidate record against restaurant-arena-trace-v3, field by
 * field. A malformed record comes back with one error per offending path
 * rather than a single "invalid" verdict, so the caller can say what to fix.
 */
export function validateArenaTraceV3(record: unknown): TraceValidationResult {
  const check = new FieldChecker();
  if (!check.object("", record, TRACE_REQUIRED, TRACE_TOP_LEVEL)) {
    return { valid: false, errors: check.errors };
  }
  const trace = record as Record<string, unknown>;

  check.const("version", trace.version, TRACE_V3_VERSION);
  check.arenaId("episodeId", trace.episodeId);
  if (trace.sessionId !== undefined) check.arenaId("sessionId", trace.sessionId);
  check.integer("seed", trace.seed, 0);
  check.string("envVersion", trace.envVersion, 1);
  check.const("contractVersion", trace.contractVersion, TRACE_V3_CONTRACT_VERSION);
  check.enum("runKind", trace.runKind, RUN_KINDS);

  checkArenaStateV1(check, "initialState", trace.initialState);

  if (check.array("events", trace.events)) {
    (trace.events as unknown[]).forEach((event, index) => checkTraceEvent(check, `events[${index}]`, event));
  }

  if (check.object("deletion", trace.deletion, ["requestId", "status"], ["requestId", "status"])) {
    const deletion = trace.deletion as Record<string, unknown>;
    if (deletion.requestId !== null) check.arenaId("deletion.requestId", deletion.requestId);
    check.enum("deletion.status", deletion.status, ["retained", "requested", "deleted"]);
  }

  const terminalFields = ["status", "tick", "reason"] as const;
  if (check.object("terminal", trace.terminal, terminalFields, terminalFields)) {
    const terminal = trace.terminal as Record<string, unknown>;
    check.enum("terminal.status", terminal.status, ["active", "completed", "abandoned"]);
    check.integer("terminal.tick", terminal.tick, 0);
    check.nullableString("terminal.reason", terminal.reason);
  }

  const replayFields = ["variation", "inputs", "finalStateHash", "finalRestaurantStateHash"] as const;
  if (check.object("replay", trace.replay, ["variation", "inputs", "finalStateHash"], replayFields)) {
    const replay = trace.replay as Record<string, unknown>;
    check.enum("replay.variation", replay.variation, REPLAY_VARIATIONS);
    check.stateHash("replay.finalStateHash", replay.finalStateHash);
    if (replay.finalRestaurantStateHash !== undefined) {
      check.stateHash("replay.finalRestaurantStateHash", replay.finalRestaurantStateHash);
    }
    if (check.array("replay.inputs", replay.inputs)) {
      (replay.inputs as unknown[]).forEach((input, index) => checkReplayInput(check, `replay.inputs[${index}]`, input));
    }
  }

  return { valid: check.errors.length === 0, errors: check.errors };
}

toolUseResult.oldString:
export function computeStateHash(data: unknown): string {
  const json = typeof data === "string" ? data : canonicalJson(data);
  return sha256Bytes(new TextEncoder().encode(json));
}

toolUseResult.newString:
export function computeStateHash(data: unknown): string {
  const json = typeof data === "string" ? data : canonicalJson(data);
  return sha256Bytes(new TextEncoder().encode(json));
}

// ── Capture ──────────────────────────────────────────────────────────────

/** Milliseconds of wall clock a trace attributes to one simulation tick. */
const MS_PER_TICK = 3000;

export interface TraceCaptureOptions {
  /** Defaults to the run's own `episode.id`. */
  episodeId?: string;
  /**
   * The one run this trace came from. Left off when the caller has no session
   * id to quote; see `RestaurantArenaTraceV3.sessionId`.
   */
  sessionId?: string;
  /** Required: live gameplay, synthetic episodes and benchmark episodes must stay distinguishable. */
  runKind: "live" | "synthetic" | "benchmark";
  /** Defaults to the arena build this module was published with. */
  envVersion?: string;
  /**
   * Wall clock for tick 0. Supplied by deterministic exporters so the same
   * seed produces the same bytes; the run's own clock is used when omitted.
   */
  startTime?: string;
  deletion?: Partial<TraceV3Deletion>;
  /** Omit to capture the run's own recorded event journal; pass to replace it wholesale. */
  events?: TraceV3Event[];
  /**
   * Events the caller wants merged into the captured journal alongside the
   * game's own recorded events (e.g. an out-of-band player note). Each one is
   * stamped with the round its `tick` falls in — round *r* covers ticks 2r-1
   * and 2r, tick 0 is round 1 — and merged in tick order, after any recorded
   * event on the same tick.
   */
  additionalEvents?: TraceV3Event[];
}

const RUN_KINDS: readonly TraceCaptureOptions["runKind"][] = ["live", "synthetic", "benchmark"];

/**
 * Re-stamp a journal onto a caller-supplied tick-0 wall clock. The engine
 * derives every event timestamp from `startTime + tick * 3s`, so an exporter
 * that wants byte-stable output only has to name tick 0.
 */
function restampEvents(events: TraceV3Event[], startMs: number): TraceV3Event[] {
  return events.map((event) => ({
    ...event,
    timestamp: new Date(startMs + event.tick * MS_PER_TICK).toISOString(),
  }));
}

/**
 * Fold caller-supplied events into the recorded journal in tick order,
 * stamping each with the round its tick belongs to. Ties keep the recorded
 * event first: the journal is the run's own account, the extras annotate it.
 */
function mergeAdditionalEvents(
  recorded: TraceV3Event[],
  additional: TraceV3Event[],
  ticksPerRound: number,
): TraceV3Event[] {
  const stamped = additional.map((event) => ({ ...event, round: roundForTick(event.tick, ticksPerRound) }));
  return [...recorded, ...stamped]
    .map((event, order) => ({ event, order }))
    .sort((a, b) => a.event.tick - b.event.tick || a.order - b.order)
    .map(({ event }) => event);
}

/**
 * Turn a running game into a complete restaurant-arena-trace-v3 record: the
 * world at tick 0, the event journal, the ordered replay inputs with their
 * checkpoint hashes, and the terminal record as the engine reports it.
 *
 * `RestaurantGame.captureTrace` is the instance-method form of this and
 * delegates straight here, so a caller can use either.
 */
export function captureArenaTrace(
  game: RestaurantGame,
  options: TraceCaptureOptions,
): RestaurantArenaTraceV3 {
  if (options === null || typeof options !== "object") {
    throw new TypeError("captureArenaTrace requires capture options naming a runKind");
  }
  if (!RUN_KINDS.includes(options.runKind)) {
    throw new TypeError(
      `captureArenaTrace requires runKind of ${RUN_KINDS.join(", ")}; got ${JSON.stringify(options.runKind)}`,
    );
  }
  if (options.startTime !== undefined && Number.isNaN(Date.parse(options.startTime))) {
    throw new TypeError(`captureArenaTrace startTime is not a date-time: ${JSON.stringify(options.startTime)}`);
  }

  const state = game.state();
  const initialState = game.getInitialState();
  const seed = typeof initialState.seed === "number" ? initialState.seed : state.seed;
  const recorded =
    options.events ??
    (options.startTime === undefined
      ? game.getRecordedEvents()
      : restampEvents(game.getRecordedEvents(), Date.parse(options.startTime)));
  const events = options.additionalEvents?.length
    ? mergeAdditionalEvents(recorded, options.additionalEvents, game.contract().ticksPerRound)
    : recorded;

  return {
    version: TRACE_V3_VERSION,
    episodeId: options.episodeId ?? state.episode.id ?? `dinner-rush-${seed}`,
    ...(options.sessionId === undefined ? {} : { sessionId: options.sessionId }),
    seed,
    envVersion: options.envVersion ?? ARENA_ENV_VERSION,
    contractVersion: TRACE_V3_CONTRACT_VERSION,
    runKind: options.runKind,
    initialState,
    events,
    replay: game.getReplayRecord(),
    terminal: game.getTerminalStatus(),
    deletion: {
      requestId: options.deletion?.requestId ?? null,
      status: options.deletion?.status ?? "retained",
    },
  };
}

// ── Export ───────────────────────────────────────────────────────────────

/**
 * The whole record as one pretty-printed JSON document, in field order and
 * with the backend's decimal spelling for float fields, so a re-export of an
 * unchanged run is byte-identical to the file already on disk.
 */
export function exportTraceJson(trace: RestaurantArenaTraceV3): string {
  return `${serializeJson(trace, true, false) ?? "null"}\n`;
}

/**
 * The streaming form: a header line carrying everything but the journal,
 * then one line per event in recorded order.
 */
export function exportTraceJsonl(trace: RestaurantArenaTraceV3): string {
  const { events, ...header } = trace;
  return `${[JSON.stringify(header), ...events.map((event) => JSON.stringify(event))].join("\n")}\n`;
}

/** Re-join a JSONL export into the record `exportTraceJsonl` was given. */
export function parseTraceJsonl(text: string): RestaurantArenaTraceV3 {
  const lines = text.split("\n").filter((line) => line.trim().length > 0);
  const [header, ...eventLines] = lines;
  if (header === undefined) throw new Error("trace JSONL is empty: no header line");
  const parsed = JSON.parse(header) as Record<string, unknown>;
  const events = eventLines.map((line) => JSON.parse(line) as TraceV3Event);
  // Restore the recorded field order, so a JSONL round trip re-exports as JSON
  // identically: `events` sits between `initialState` and `replay`.
  const { replay, terminal, deletion, ...head } = parsed;
  return { ...head, events, replay, terminal, deletion } as unknown as RestaurantArenaTraceV3;
}

// ── Validation ───────────────────────────────────────────────────────────

export interface TraceValidationResult {
  valid: boolean;
  errors: string[];
}

const ARENA_ID = /^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$/;
const IDEMPOTENCY_KEY = /^[A-Za-z0-9][A-Za-z0-9._:-]{0,129}$/;
const STATE_HASH = /^sha256:[0-9a-f]{64}$/;
const DATE_TIME = /^\d{4}-\d{2}-\d{2}[Tt]\d{2}:\d{2}:\d{2}(\.\d+)?([Zz]|[+-]\d{2}:\d{2})$/;

const TRACE_ROLES = ["host", "supply_lead", "chef", "server", "expediter"] as const;
const TRACE_EVENT_KINDS: readonly TraceEventKind[] = [
  "observation", "action", "player_correction", "message", "outcome", "inspection",
  "hold", "hold_cleared", "verification_request", "verification_response",
  "escalation", "handoff", "supply_order", "supply_delivered", "stockout",
];
const REPLAY_VARIATIONS = ["tutorial-shift", "dinner-rush", "quiet-tuesday", "saturday-night"] as const;
const ACTION_TOOLS = [
  "inspect", "prepare", "serve", "seat", "update_guest",
  "coordinate", "request_help", "send_message", "approve", "correct",
] as const;

/**
 * One record's worth of field-by-field complaints. Every check names the path
 * it failed on, because "invalid trace" tells a caller holding a 400-event
 * export nothing about which field to look at.
 */
class FieldChecker {
  readonly errors: string[] = [];

  fail(path: string, expected: string): false {
    this.errors.push(`${path || "record"}: ${expected}`);
    return false;
  }

  /** An object with no keys beyond `allowed` and none of `required` missing. */
  object(
    path: string,
    value: unknown,
    required: readonly string[],
    allowed: readonly string[],
  ): value is Record<string, unknown> {
    if (typeof value !== "object" || value === null || Array.isArray(value)) {
      return this.fail(path, "expected an object");
    }
    const record = value as Record<string, unknown>;
    const child = (key: string) => (path ? `${path}.${key}` : key);
    let ok = true;
    for (const key of required) {
      if (record[key] === undefined) ok = this.fail(child(key), "is required");
    }
    for (const key of Object.keys(record)) {
      if (!allowed.includes(key)) ok = this.fail(child(key), "is not a known field");
    }
    return ok;
  }

  array(path: string, value: unknown): value is unknown[] {
    return Array.isArray(value) ? true : this.fail(path, "expected an array");
  }

  const(path: string, value: unknown, expected: string): boolean {
    return value === expected ? true : this.fail(path, `expected ${JSON.stringify(expected)}`);
  }

  enum<T extends string>(path: string, value: unknown, allowed: readonly T[]): boolean {
    return allowed.includes(value as T) ? true : this.fail(path, `expected one of ${allowed.join(", ")}`);
  }

  string(path: string, value: unknown, minLength = 0): boolean {
    if (typeof value !== "string") return this.fail(path, "expected a string");
    return value.length >= minLength ? true : this.fail(path, `expected at least ${minLength} character(s)`);
  }

  pattern(path: string, value: unknown, re: RegExp, described: string): boolean {
    if (typeof value !== "string") return this.fail(path, "expected a string");
    return re.test(value) ? true : this.fail(path, `expected ${described}`);
  }

  integer(path: string, value: unknown, min?: number, max?: number): boolean {
    if (typeof value !== "number" || !Number.isInteger(value)) return this.fail(path, "expected an integer");
    if (min !== undefined && value < min) return this.fail(path, `expected an integer >= ${min}`);
    if (max !== undefined && value > max) return this.fail(path, `expected an integer <= ${max}`);
    return true;
  }

  number(path: string, value: unknown, min?: number, max?: number): boolean {
    if (typeof value !== "number" || !Number.isFinite(value)) return this.fail(path, "expected a number");
    if (min !== undefined && value < min) return this.fail(path, `expected a number >= ${min}`);
    if (max !== undefined && value > max) return this.fail(path, `expected a number <= ${max}`);
    return true;
  }

  boolean(path: string, value: unknown): boolean {
    return typeof value === "boolean" ? true : this.fail(path, "expected a boolean");
  }

  /** A nullable free-form object, as the payload-shaped event fields are. */
  nullableObject(path: string, value: unknown): boolean {
    if (value === null) return true;
    if (typeof value !== "object" || Array.isArray(value)) return this.fail(path, "expected an object or null");
    return true;
  }

  nullableString(path: string, value: unknown): boolean {
    if (value === null) return true;
    return typeof value === "string" ? true : this.fail(path, "expected a string or null");
  }

  dateTime(path: string, value: unknown): boolean {
    if (!this.pattern(path, value, DATE_TIME, "an RFC 3339 date-time")) return false;
    return Number.isNaN(Date.parse(value as string)) ? this.fail(path, "expected a parsable date-time") : true;
  }

  arenaId(path: string, value: unknown): boolean {
    return this.pattern(path, value, ARENA_ID, "an arena id (alphanumeric start, then [A-Za-z0-9._-], max 64)");
  }

  stateHash(path: string, value: unknown): boolean {
    return this.pattern(path, value, STATE_HASH, "a sha256: hash of 64 lowercase hex digits");
  }
}

const STATE_TOP_LEVEL = [
  "version", "seed", "episode", "clock", "tables", "orders", "inventory",
  "equipment", "workers", "emergency", "reputation", "outcomes",
] as const;

/** `restaurant-arena-state-v1`, checked field by field. */
function checkArenaStateV1(check: FieldChecker, path: string, value: unknown): void {
  const required = STATE_TOP_LEVEL.filter((key) => key !== "emergency");
  if (!check.object(path, value, required, STATE_TOP_LEVEL)) return;
  const state = value as Record<string, unknown>;

  check.const(`${path}.version`, state.version, "restaurant-arena/v1");
  check.integer(`${path}.seed`, state.seed, 0);

  const episodeFields = ["id", "phase", "tick", "maxTicks"] as const;
  if (check.object(`${path}.episode`, state.episode, episodeFields, episodeFields)) {
    const episode = state.episode as Record<string, unknown>;
    check.arenaId(`${path}.episode.id`, episode.id);
    check.enum(`${path}.episode.phase`, episode.phase, ["active", "complete"]);
    check.integer(`${path}.episode.tick`, episode.tick, 0);
    check.integer(`${path}.episode.maxTicks`, episode.maxTicks, 1);
  }

  if (check.object(`${path}.clock`, state.clock, ["minute", "speed"], ["minute", "speed"])) {
    const clock = state.clock as Record<string, unknown>;
    check.integer(`${path}.clock.minute`, clock.minute, 0);
    check.integer(`${path}.clock.speed`, clock.speed, 1);
  }

  if (check.array(`${path}.tables`, state.tables)) {
    (state.tables as unknown[]).forEach((table, index) => {
      const at = `${path}.tables[${index}]`;
      if (!check.object(at, table, ["id", "seats", "status"], ["id", "seats", "status", "orderId"])) return;
      const row = table as Record<string, unknown>;
      check.arenaId(`${at}.id`, row.id);
      check.integer(`${at}.seats`, row.seats, 1);
      check.enum(`${at}.status`, row.status, ["empty", "occupied"]);
      if (row.orderId !== undefined) check.arenaId(`${at}.orderId`, row.orderId);
    });
  }

  if (check.array(`${path}.orders`, state.orders)) {
    (state.orders as unknown[]).forEach((order, index) => {
      const at = `${path}.orders[${index}]`;
      const allowed = ["id", "tableId", "items", "status", "allergy", "priority"];
      if (!check.object(at, order, ["id", "items", "status", "priority"], allowed)) return;
      const row = order as Record<string, unknown>;
      check.arenaId(`${at}.id`, row.id);
      if (row.tableId !== undefined) check.arenaId(`${at}.tableId`, row.tableId);
      if (check.array(`${at}.items`, row.items)) {
        (row.items as unknown[]).forEach((item, itemIndex) => check.string(`${at}.items[${itemIndex}]`, item, 1));
      }
      check.enum(`${at}.status`, row.status, ["queued", "seated", "preparing", "ready", "served", "cancelled"]);
      if (row.allergy !== undefined) check.string(`${at}.allergy`, row.allergy, 1);
      check.enum(`${at}.priority`, row.priority, ["normal", "high"]);
    });
  }

  if (typeof state.inventory !== "object" || state.inventory === null || Array.isArray(state.inventory)) {
    check.fail(`${path}.inventory`, "expected an object");
  } else {
    for (const [item, count] of Object.entries(state.inventory as Record<string, unknown>)) {
      check.integer(`${path}.inventory.${item}`, count, 0);
    }
  }

  if (check.array(`${path}.equipment`, state.equipment)) {
    (state.equipment as unknown[]).forEach((item, index) => {
      const at = `${path}.equipment[${index}]`;
      const allowed = ["id", "kind", "status", "safetyThreshold", "reading"];
      if (!check.object(at, item, ["id", "kind", "status"], allowed)) return;
      const row = item as Record<string, unknown>;
      check.arenaId(`${at}.id`, row.id);
      check.enum(`${at}.kind`, row.kind, ["oven", "warming_shelf"]);
      check.enum(`${at}.status`, row.status, ["working", "failed", "degraded"]);
      if (row.safetyThreshold !== undefined) check.number(`${at}.safetyThreshold`, row.safetyThreshold);
      if (row.reading !== undefined) check.number(`${at}.reading`, row.reading);
    });
  }

  if (check.array(`${path}.workers`, state.workers)) {
    (state.workers as unknown[]).forEach((worker, index) => {
      const at = `${path}.workers[${index}]`;
      const allowed = ["id", "role", "load", "location", "lastAction"];
      if (!check.object(at, worker, ["id", "role", "load", "location"], allowed)) return;
      const row = worker as Record<string, unknown>;
      check.arenaId(`${at}.id`, row.id);
      check.enum(`${at}.role`, row.role, TRACE_ROLES);
      check.number(`${at}.load`, row.load, 0, 1);
      check.enum(`${at}.location`, row.location, ["floor", "kitchen", "pass", "queue"]);
      if (row.lastAction !== undefined) check.string(`${at}.lastAction`, row.lastAction);
    });
  }

  const emergencyFields = ["kind", "active", "startedAt"] as const;
  if (state.emergency !== undefined && check.object(`${path}.emergency`, state.emergency, emergencyFields, emergencyFields)) {
    const emergency = state.emergency as Record<string, unknown>;
    check.const(`${path}.emergency.kind`, emergency.kind, "oven_failure");
    check.boolean(`${path}.emergency.active`, emergency.active);
    check.integer(`${path}.emergency.startedAt`, emergency.startedAt, 0);
  }

  check.number(`${path}.reputation`, state.reputation, 0, 100);

  const outcomeKeys = [
    "cash", "satisfaction", "waste", "waitTime",
    "completed", "safeOrders", "coordination", "correctionUptake",
  ] as const;
  if (check.object(`${path}.outcomes`, state.outcomes, outcomeKeys, outcomeKeys)) {
    const outcomes = state.outcomes as Record<string, unknown>;
    check.number(`${path}.outcomes.cash`, outcomes.cash, 0);
    check.number(`${path}.outcomes.satisfaction`, outcomes.satisfaction, 0, 1);
    check.number(`${path}.outcomes.waste`, outcomes.waste, 0);
    check.number(`${path}.outcomes.waitTime`, outcomes.waitTime, 0);
    check.integer(`${path}.outcomes.completed`, outcomes.completed, 0);
    check.integer(`${path}.outcomes.safeOrders`, outcomes.safeOrders, 0);
    check.number(`${path}.outcomes.coordination`, outcomes.coordination, 0, 1);
    check.number(`${path}.outcomes.correctionUptake`, outcomes.correctionUptake, 0, 1);
  }
}

const EVENT_FIELDS = [
  "tick", "round", "kind", "timestamp", "stateHash", "actorId", "role", "targetRole",
  "checkpointId", "model", "requestId", "idempotencyKey", "text", "observation",
  "action", "toolResult", "outcome", "correctionRationale", "correctionCategory",
  "changedDecisionEventId", "probeEventId", "subject", "payload",
] as const;

function checkTraceEvent(check: FieldChecker, path: string, value: unknown): void {
  if (!check.object(path, value, ["tick", "kind", "timestamp", "stateHash"], EVENT_FIELDS)) return;
  const event = value as Record<string, unknown>;

  check.integer(`${path}.tick`, event.tick, 0);
  check.enum(`${path}.kind`, event.kind, TRACE_EVENT_KINDS);
  check.dateTime(`${path}.timestamp`, event.timestamp);
  check.stateHash(`${path}.stateHash`, event.stateHash);
  if (event.round !== undefined) check.integer(`${path}.round`, event.round, 1);
  if (event.actorId !== undefined) check.arenaId(`${path}.actorId`, event.actorId);
  if (event.role !== undefined) check.enum(`${path}.role`, event.role, TRACE_ROLES);
  if (event.targetRole !== undefined) check.enum(`${path}.targetRole`, event.targetRole, TRACE_ROLES);
  if (event.checkpointId !== undefined) check.arenaId(`${path}.checkpointId`, event.checkpointId);
  if (event.requestId !== undefined) check.arenaId(`${path}.requestId`, event.requestId);
  if (event.idempotencyKey !== undefined) {
    check.pattern(
      `${path}.idempotencyKey`,
      event.idempotencyKey,
      IDEMPOTENCY_KEY,
      "an idempotency key of up to 130 [A-Za-z0-9._:-] characters",
    );
  }
  if (event.text !== undefined) check.nullableString(`${path}.text`, event.text);
  if (event.observation !== undefined) check.nullableObject(`${path}.observation`, event.observation);
  if (event.action !== undefined) check.nullableObject(`${path}.action`, event.action);
  if (event.outcome !== undefined) check.nullableObject(`${path}.outcome`, event.outcome);
  if (event.payload !== undefined) check.nullableObject(`${path}.payload`, event.payload);
  if (event.correctionRationale !== undefined) check.nullableString(`${path}.correctionRationale`, event.correctionRationale);
  if (event.correctionCategory !== undefined && event.correctionCategory !== null) {
    check.enum(`${path}.correctionCategory`, event.correctionCategory, ["safety", "priority", "quality", "pace"]);
  }
  for (const key of ["changedDecisionEventId", "probeEventId"] as const) {
    if (event[key] !== undefined && event[key] !== null) check.arenaId(`${path}.${key}`, event[key]);
  }

  const modelFields = ["provider", "name", "version"] as const;
  if (event.model !== undefined && check.object(`${path}.model`, event.model, ["provider", "name"], modelFields)) {
    const model = event.model as Record<string, unknown>;
    check.string(`${path}.model.provider`, model.provider, 1);
    check.string(`${path}.model.name`, model.name, 1);
    if (model.version !== undefined) check.string(`${path}.model.version`, model.version, 1);
  }

  if (event.subject !== undefined && check.object(`${path}.subject`, event.subject, ["kind", "id"], ["kind", "id"])) {
    const subject = event.subject as Record<string, unknown>;
    check.enum(`${path}.subject.kind`, subject.kind, ["order", "ingredient", "equipment", "handoff"]);
    check.arenaId(`${path}.subject.id`, subject.id);
  }

  if (event.toolResult !== undefined && event.toolResult !== null) {
    checkToolResult(check, `${path}.toolResult`, event.toolResult);
  }
}

/** The three reserved keys a grader sorts on, and the ok/error agreement between them. */
function checkToolResult(check: FieldChecker, path: string, value: unknown): void {
  if (typeof value !== "object" || value === null || Array.isArray(value)) {
    check.fail(path, "expected an object or null");
    return;
  }
  const result = value as Record<string, unknown>;
  if (result.ok !== undefined) check.boolean(`${path}.ok`, result.ok);
  if (result.latencyMs !== undefined) check.number(`${path}.latencyMs`, result.latencyMs, 0);
  if (result.error === undefined || result.error === null) {
    if (result.ok === false) check.fail(`${path}.error`, "is required when ok is false");
    return;
  }
  const errorFields = ["code", "message", "retryable"] as const;
  if (check.object(`${path}.error`, result.error, ["code", "message"], errorFields)) {
    const error = result.error as Record<string, unknown>;
    check.string(`${path}.error.code`, error.code, 1);
    check.string(`${path}.error.message`, error.message, 1);
    if (error.retryable !== undefined) check.boolean(`${path}.error.retryable`, error.retryable);
  }
  // A consumer filtering on `ok` and one filtering on error presence must not
  // disagree about the same event.
  if (result.ok !== false) check.fail(`${path}.ok`, "expected false, because an error body means the call failed");
}

function checkActionEnvelopeV1(check: FieldChecker, path: string, value: unknown): void {
  const fields = [
    "version", "episodeId", "actorId", "actorType", "role", "tool",
    "arguments", "tick", "timestamp", "requestId", "idempotencyKey",
  ] as const;
  if (!check.object(path, value, fields, fields)) return;
  const envelope = value as Record<string, unknown>;
  check.const(`${path}.version`, envelope.version, "restaurant-arena-action/v1");
  check.arenaId(`${path}.episodeId`, envelope.episodeId);
  check.arenaId(`${path}.actorId`, envelope.actorId);
  check.enum(`${path}.actorType`, envelope.actorType, ["worker", "player"]);
  check.enum(`${path}.role`, envelope.role, TRACE_ROLES);
  check.enum(`${path}.tool`, envelope.tool, ACTION_TOOLS);
  if (typeof envelope.arguments !== "object" || envelope.arguments === null || Array.isArray(envelope.arguments)) {
    check.fail(`${path}.arguments`, "expected an object");
  }
  check.integer(`${path}.tick`, envelope.tick, 0);
  check.dateTime(`${path}.timestamp`, envelope.timestamp);
  check.arenaId(`${path}.requestId`, envelope.requestId);
  check.pattern(
    `${path}.idempotencyKey`,
    envelope.idempotencyKey,
    IDEMPOTENCY_KEY,
    "an idempotency key of up to 130 [A-Za-z0-9._:-] characters",
  );
}

const HASH_FIELDS = ["kind", "tick", "stateHash", "restaurantStateHash"] as const;
const INPUT_SHAPES = {
  step: { required: ["kind", "tick", "stateHash", "action"], allowed: [...HASH_FIELDS, "action"] },
  time: { required: ["kind", "tick", "stateHash"], allowed: [...HASH_FIELDS] },
  envelope: { required: ["kind", "tick", "stateHash", "envelope"], allowed: [...HASH_FIELDS, "envelope", "telemetry"] },
  controllers: { required: ["kind", "tick", "stateHash", "roles"], allowed: [...HASH_FIELDS, "roles"] },
} as const;

function checkReplayInput(check: FieldChecker, path: string, value: unknown): void {
  if (typeof value !== "object" || value === null || Array.isArray(value)) {
    check.fail(path, "expected an object");
    return;
  }
