const TRACE_TOP_LEVEL = [
  "version", "episodeId", "sessionId", "seed", "envVersion", "contractVersion",
  "runKind", "initialState", "events", "replay", "terminal", "deletion",
] as const;

const TRACE_REQUIRED = TRACE_TOP_LEVEL.filter((key) => key !== "sessionId");

/**
 * Validate a candidate record against restaurant-arena-trace-v3, field by
 * field. A malformed record comes back with one error per offending path
 * rather than a single "invalid" verdict, so the caller can say what to fix.
 */
export function validateArenaTraceV3(record: unknown): TraceValidationResult {
  const check = new FieldChecker();
  if (!check.object("", record, TRACE_REQUIRED, TRACE_TOP_LEVEL)) {
    return { valid: false, errors: check.errors };
  }
  const trace = record as Record<string, unknown>;

  check.const("version", trace.version, TRACE_V3_VERSION);
  check.arenaId("episodeId", trace.episodeId);
  if (trace.sessionId !== undefined) check.arenaId("sessionId", trace.sessionId);
  check.integer("seed", trace.seed, 0);
  check.string("envVersion", trace.envVersion, 1);
  check.const("contractVersion", trace.contractVersion, TRACE_V3_CONTRACT_VERSION);
  check.enum("runKind", trace.runKind, RUN_KINDS);

  checkArenaStateV1(check, "initialState", trace.initialState);

  if (check.array("events", trace.events)) {
    (trace.events as unknown[]).forEach((event, index) => checkTraceEvent(check, `events[${index}]`, event));
  }

  if (check.object("deletion", trace.deletion, ["requestId", "status"], ["requestId", "status"])) {
    const deletion = trace.deletion as Record<string, unknown>;
    if (deletion.requestId !== null) check.arenaId("deletion.requestId", deletion.requestId);
    check.enum("deletion.status", deletion.status, ["retained", "requested", "deleted"]);
  }

  const terminalFields = ["status", "tick", "reason"] as const;
  if (check.object("terminal", trace.terminal, terminalFields, terminalFields)) {
    const terminal = trace.terminal as Record<string, unknown>;
    check.enum("terminal.status", terminal.status, ["active", "completed", "abandoned"]);
    check.integer("terminal.tick", terminal.tick, 0);
    check.nullableString("terminal.reason", terminal.reason);
  }

  const replayFields = ["variation", "inputs", "finalStateHash", "finalRestaurantStateHash"] as const;
  if (check.object("replay", trace.replay, ["variation", "inputs", "finalStateHash"], replayFields)) {
    const replay = trace.replay as Record<string, unknown>;
    check.enum("replay.variation", replay.variation, REPLAY_VARIATIONS);
    check.stateHash("replay.finalStateHash", replay.finalStateHash);
    if (replay.finalRestaurantStateHash !== undefined) {
      check.stateHash("replay.finalRestaurantStateHash", replay.finalRestaurantStateHash);
    }
    if (check.array("replay.inputs", replay.inputs)) {
      (replay.inputs as unknown[]).forEach((input, index) => checkReplayInput(check, `replay.inputs[${index}]`, input));
    }
  }

  return { valid: check.errors.length === 0, errors: check.errors };
}

