/**
 * Native replay of a `restaurant-arena-trace-v3` record.
 *
 * A trace is only evidence if the engine that wrote it can be made to walk
 * the same shift again and land in the same place. So replay never trusts the
 * record: it builds a fresh `RestaurantGame` from the seed, re-applies the
 * recorded inputs one at a time, and checks its own checkpoint against every
 * hash the record carries — the tick-0 state, each input, the final state,
 * and the terminal record. Any disagreement throws.
 */

import { RestaurantGame, type ArenaInputRecord, type RestaurantGameAction } from "./restaurant-game.js";
import { computeStateHash, type RestaurantArenaTraceV3 } from "./trace.js";

/**
 * Roles renamed since v1 exports were written. Only the *name* is legacy: the
 * supply lead does what the expediter did, so a historical trace naming the
 * old roster still replays to the same outcome.
 */
const LEGACY_ROLE_ALIASES: Readonly<Record<string, string>> = { expediter: "supply_lead" };
const LEGACY_WORKER_ID_ALIASES: Readonly<Record<string, string>> = { "worker-expediter": "worker-supply_lead" };

/**
 * Put a recorded tick-0 state and the engine's own tick-0 state on the same
 * footing before hashing them: legacy role names mapped forward, and the
 * roster in a fixed order, because which slot a worker occupies in the array
 * is not a fact about the world. Nothing else is normalised — every other
 * field has to match what this seed actually produces.
 */
function canonicalizeInitialState(state: Record<string, unknown>): Record<string, unknown> {
  const clone = JSON.parse(JSON.stringify(state)) as Record<string, unknown>;
  const workers = clone.workers;
  if (!Array.isArray(workers)) return clone;
  for (const worker of workers as Record<string, unknown>[]) {
    if (worker === null || typeof worker !== "object") continue;
    const role = worker.role;
    if (typeof role === "string" && LEGACY_ROLE_ALIASES[role]) worker.role = LEGACY_ROLE_ALIASES[role];
    const id = worker.id;
    if (typeof id === "string" && LEGACY_WORKER_ID_ALIASES[id]) worker.id = LEGACY_WORKER_ID_ALIASES[id];
  }
  (workers as Record<string, unknown>[]).sort((a, b) => String(a?.id ?? "").localeCompare(String(b?.id ?? "")));
  return clone;
}

function describeInput(input: ArenaInputRecord, index: number): string {
  return `replay.inputs[${index}] (${input.kind} at tick ${input.tick})`;
}

/**
 * Apply one recorded input to a live game and check the checkpoint it lands
 * on against the one the record claims. Throws on any disagreement, so a
 * caller stepping through a trace for animation gets the same guarantee
 * `replayArenaTrace` gives in one shot.
 *
 * `index` only sharpens the error message; it is the input's position in
 * `trace.replay.inputs`.
 */
export function applyArenaReplayInput(
  game: RestaurantGame,
  input: ArenaInputRecord,
  index = 0,
): void {
  const at = describeInput(input, index);
  const tickBefore = game.state().episode.tick;
  if (tickBefore !== input.tick) {
    throw new Error(`${at}: recorded tick ${input.tick}, replay was at tick ${tickBefore}`);
  }

  switch (input.kind) {
    case "step":
      game.step(input.action as RestaurantGameAction);
      break;
    case "time":
      game.advanceTime();
      break;
    case "envelope":
      game.stepEnvelope(input.envelope, input.telemetry);
      break;
    case "controllers":
      game.setExternalControllers(input.roles);
      break;
    default:
      throw new Error(`${at}: unknown replay input kind ${JSON.stringify((input as { kind: unknown }).kind)}`);
  }

  const stateHash = computeStateHash(game.checkpointState());
  if (stateHash !== input.stateHash) {
    throw new Error(`${at}: checkpoint hash mismatch — recorded ${input.stateHash}, replay produced ${stateHash}`);
  }
  if (input.restaurantStateHash !== undefined) {
    const restaurantStateHash = computeStateHash(game.state());
    if (restaurantStateHash !== input.restaurantStateHash) {
      throw new Error(
        `${at}: restaurant state hash mismatch — recorded ${input.restaurantStateHash}, replay produced ${restaurantStateHash}`,
      );
    }
  }
}

/**
 * Rebuild the live game a trace was captured from and return it.
 *
 * The returned value is the `RestaurantGame` itself, so a caller can go on to
 * ask it anything — `.state()`, `.checkpointState()`, `.getTerminalStatus()`.
 * Throws if the record and the engine disagree anywhere along the way.
 */
export function replayArenaTrace(trace: RestaurantArenaTraceV3): RestaurantGame {
  if (trace === null || typeof trace !== "object") {
    throw new Error("replayArenaTrace requires a restaurant-arena-trace-v3 record");
  }
  const replay = trace.replay;
  if (replay === null || typeof replay !== "object" || !Array.isArray(replay.inputs)) {
    throw new Error("replayArenaTrace requires trace.replay with an inputs array");
  }

  const game = new RestaurantGame(trace.seed, replay.variation);

  // The recorded tick-0 state is checked against what this engine's own seed
  // produces, never taken on faith: a trace whose initialState was edited in
  // any field still parses, but it no longer describes this episode.
  const expectedInitialHash = computeStateHash(canonicalizeInitialState(game.getInitialState()));
  const recordedInitialHash = computeStateHash(canonicalizeInitialState(trace.initialState));
  if (expectedInitialHash !== recordedInitialHash) {
    throw new Error(
      `initial state mismatch — seed ${trace.seed} produces ${expectedInitialHash}, trace.initialState hashes to ${recordedInitialHash}`,
    );
  }

  replay.inputs.forEach((input, index) => applyArenaReplayInput(game, input, index));

  const finalStateHash = computeStateHash(game.checkpointState());
  if (finalStateHash !== replay.finalStateHash) {
    throw new Error(
      `final state hash mismatch — recorded ${replay.finalStateHash}, replay produced ${finalStateHash}`,
    );
  }
  if (replay.finalRestaurantStateHash !== undefined) {
    const finalRestaurantStateHash = computeStateHash(game.state());
    if (finalRestaurantStateHash !== replay.finalRestaurantStateHash) {
      throw new Error(
        `final restaurant state hash mismatch — recorded ${replay.finalRestaurantStateHash}, replay produced ${finalRestaurantStateHash}`,
      );
    }
  }

  // The whole terminal record, not just the status: a shift that ended for a
  // different reason, or on a different tick, is a different shift.
  const terminal = game.getTerminalStatus();
  const recorded = trace.terminal;
  if (
    recorded === null ||
    typeof recorded !== "object" ||
    recorded.status !== terminal.status ||
    recorded.tick !== terminal.tick ||
    (recorded.reason ?? null) !== terminal.reason
  ) {
    throw new Error(
      `terminal mismatch — recorded ${JSON.stringify(recorded)}, replay produced ${JSON.stringify(terminal)}`,
    );
  }

  return game;
}

