    const finalRestaurantStateHash = computeStateHash(game.state());
    if (finalRestaurantStateHash !== replay.finalRestaurantStateHash) {
      throw new Error(
        `final restaurant state hash mismatch — recorded ${replay.finalRestaurantStateHash}, replay produced ${finalRestaurantStateHash}`,
      );
    }
  }

  // The whole terminal record, not just the status: a shift that ended for a
  // different reason, or on a different tick, is a different shift.
  const terminal = game.getTerminalStatus();
  const recorded = trace.terminal;
  if (
    recorded === null ||
    typeof recorded !== "object" ||
    recorded.status !== terminal.status ||
    recorded.tick !== terminal.tick ||
    (recorded.reason ?? null) !== terminal.reason
  ) {
    throw new Error(
      `terminal mismatch — recorded ${JSON.stringify(recorded)}, replay produced ${JSON.stringify(terminal)}`,
    );
  }

  return game;
}

