#!/usr/bin/env bun
/**
 * Export (or check) the benchmark fixture trace.
 *
 *   bun scripts/export-arena-trace.ts           # write the fixture
 *   bun scripts/export-arena-trace.ts --check   # fail if the fixture is stale
 *
 * The fixture is a `restaurant-arena-trace-v3` record for one fixed benchmark
 * shift, and it has to be reproducible byte for byte: same seed, same
 * variation, same episode id, and an explicit tick-0 wall clock so the
 * journal's timestamps do not move with the machine that ran the export.
 *
 * Nothing is written until the captured record has passed both gates a
 * consumer would apply to it — schema validation and a native replay — so a
 * broken engine cannot quietly land a broken fixture.
 */

import { readFileSync, writeFileSync } from "node:fs";
import { join, relative } from "node:path";
import { RestaurantGame } from "../src/games/restaurant-arena/restaurant-game.js";
import { replayArenaTrace } from "../src/games/restaurant-arena/replay.js";
import {
  exportTraceJson,
  validateArenaTraceV3,
  type RestaurantArenaTraceV3,
} from "../src/games/restaurant-arena/trace.js";

const REPO_ROOT = join(import.meta.dir, "..");

export const FIXTURE_RELATIVE_PATH = "contracts/fixtures/restaurant-arena-trace-v3.json";
export const FIXTURE_PATH = join(REPO_ROOT, FIXTURE_RELATIVE_PATH);

const FIXTURE_SEED = 218220;
const FIXTURE_VARIATION = "dinner-rush";
const FIXTURE_EPISODE_ID = "dinner-rush-benchmark-218220";
/** Tick 0's wall clock. Frozen so re-exporting an unchanged engine is a no-op. */
const FIXTURE_START_TIME = "2026-09-05T18:00:00.000Z";

/**
 * The benchmark shift itself: open the service, run to the allergy incident,
 * hand the chef the safety correction, then let the shift play out to the
 * final whistle.
 */
export function captureFixtureTrace(): RestaurantArenaTraceV3 {
  const game = new RestaurantGame(FIXTURE_SEED, FIXTURE_VARIATION);
  game.step("sim_start");
  for (let i = 0; i < 10; i++) game.step("tick");
  game.step("verify_substitution");
  for (let i = 0; i < 14; i++) game.step("tick");
  return game.captureTrace({
    runKind: "benchmark",
    episodeId: FIXTURE_EPISODE_ID,
    startTime: FIXTURE_START_TIME,
  });
}

/** Capture the fixture and put it through the gates a consumer would apply. */
export function buildFixtureJson(): string {
  const trace = captureFixtureTrace();
  const validation = validateArenaTraceV3(trace);
  if (!validation.valid) {
    throw new Error(`captured fixture is not a valid restaurant-arena-trace-v3:\n  ${validation.errors.join("\n  ")}`);
  }
  replayArenaTrace(trace);
  return exportTraceJson(trace);
}

function main(argv: readonly string[]): number {
  const check = argv.includes("--check");
  const json = buildFixtureJson();
  const shown = relative(REPO_ROOT, FIXTURE_PATH);

  if (!check) {
    writeFileSync(FIXTURE_PATH, json);
    console.log(`Wrote ${shown} (${json.length} bytes)`);
    return 0;
  }

  let onDisk: string;
  try {
    onDisk = readFileSync(FIXTURE_PATH, "utf8");
  } catch {
    console.error(`${shown} is missing. Run: bun scripts/export-arena-trace.ts`);
    return 1;
  }
  if (onDisk === json) {
    console.log(`Fixture is current: ${shown}`);
    return 0;
  }
  console.error(`${shown} is stale. Run: bun scripts/export-arena-trace.ts`);
  const fresh = json.split("\n");
  const stale = onDisk.split("\n");
  for (let line = 0; line < Math.max(fresh.length, stale.length); line++) {
    if (fresh[line] !== stale[line]) {
      console.error(`  first difference at line ${line + 1}:`);
      console.error(`    on disk:  ${stale[line] ?? "<end of file>"}`);
      console.error(`    captured: ${fresh[line] ?? "<end of file>"}`);
      break;
    }
  }
  return 1;
}

if (import.meta.main) {
  try {
    process.exit(main(process.argv.slice(2)));
  } catch (err) {
    console.error(err instanceof Error ? err.message : String(err));
    process.exit(1);
  }
}

