#!/usr/bin/env bun
/**
 * Replay a trace file from disk and say whether the engine agrees with it.
 *
 *   bun scripts/replay-arena-trace.ts <path-to-trace.json-or-.jsonl>
 *
 * Both export shapes are accepted: the pretty JSON document from
 * `exportTraceJson` and the header-plus-events stream from
 * `exportTraceJsonl`. The record goes through `validateArenaTraceV3` and then
 * `replayArenaTrace`, which rebuilds the game from the seed and checks its own
 * checkpoints against every hash and the terminal record the file claims.
 *
 * `Native replay passed` is printed only when all of that holds. A tampered,
 * truncated or malformed file exits non-zero without printing it.
 */

import { readFileSync } from "node:fs";
import { replayArenaTrace } from "../src/games/restaurant-arena/replay.js";
import {
  parseTraceJsonl,
  validateArenaTraceV3,
  type RestaurantArenaTraceV3,
} from "../src/games/restaurant-arena/trace.js";

/**
 * Read either export shape. The extension is a hint, not the authority: a
 * whole-file JSON parse settles it, because a JSONL file's first line parses
 * on its own but the file as a whole does not.
 */
export function loadTraceFile(path: string): RestaurantArenaTraceV3 {
  const text = readFileSync(path, "utf8");
  try {
    return JSON.parse(text) as RestaurantArenaTraceV3;
  } catch {
    return parseTraceJsonl(text);
  }
}

function main(argv: readonly string[]): number {
  const path = argv.find((arg) => !arg.startsWith("-"));
  if (!path) {
    console.error("usage: bun scripts/replay-arena-trace.ts <path-to-trace.json-or-.jsonl>");
    return 1;
  }

  let trace: RestaurantArenaTraceV3;
  try {
    trace = loadTraceFile(path);
  } catch (err) {
    console.error(`Could not read a trace from ${path}: ${err instanceof Error ? err.message : String(err)}`);
    return 1;
  }

  const validation = validateArenaTraceV3(trace);
  if (!validation.valid) {
    console.error(`${path} is not a valid restaurant-arena-trace-v3 record:`);
    for (const error of validation.errors) console.error(`  ${error}`);
    return 1;
  }

  let game;
  try {
    game = replayArenaTrace(trace);
  } catch (err) {
    console.error(`Native replay failed for ${path}: ${err instanceof Error ? err.message : String(err)}`);
    return 1;
  }

  const terminal = game.getTerminalStatus();
  console.log(
    `Native replay passed: ${trace.episodeId} (${trace.runKind}, seed ${trace.seed}, ${trace.replay.variation}) — ` +
      `${trace.replay.inputs.length} inputs, ${trace.events.length} events, ` +
      `terminal ${terminal.status} at tick ${terminal.tick}${terminal.reason ? ` (${terminal.reason})` : ""}`,
  );
  return 0;
}

if (import.meta.main) {
  try {
    process.exit(main(process.argv.slice(2)));
  } catch (err) {
    console.error(err instanceof Error ? err.message : String(err));
    process.exit(1);
  }
}

