const LEGACY_NAMES: Readonly<Record<string, string>> = {
  expediter: "supply_lead",
  "worker-expediter": "worker-supply_lead",
};

/**
 * One event, reduced to what replay can reproduce: wall-clock timestamps come
 * from the machine that played the shift, and the legacy role names map
 * forward, but everything else — tick, round, kind, actor, payload, hash —
 * has to come back the same.
 */
function eventFingerprint(event: TraceV3Event): string {
  const { timestamp, ...rest } = event as TraceV3Event & Record<string, unknown>;
  const mapped: Record<string, unknown> = { ...rest };
  for (const key of ["actorId", "role", "targetRole"] as const) {
    const value = mapped[key];
    if (typeof value === "string" && LEGACY_NAMES[value]) mapped[key] = LEGACY_NAMES[value];
  }
  return canonicalJson(mapped);
}

/**
 * The recorded journal has to account for every event the engine itself
 * re-derives, in order. Hashes alone cannot catch this: a JSONL export with
 * event lines lopped off still replays its inputs perfectly, and the missing
 * events are exactly the evidence the file exists to carry. Events the record
 * has and replay does not are left alone — a capture may legitimately merge
 * caller-supplied notes into the journal.
 */
function missingJournalEvents(trace: RestaurantArenaTraceV3, game: RestaurantGame): string | undefined {
  const recorded = trace.events.map(eventFingerprint);
  const replayed = game.getRecordedEvents();
  let cursor = 0;
  for (const [index, event] of replayed.entries()) {
    const found = recorded.indexOf(eventFingerprint(event), cursor);
    if (found === -1) {
      return `recorded journal does not account for replay event ${index} (${event.kind} at tick ${event.tick}); the journal is truncated or altered`;
    }
    cursor = found + 1;
  }
  return undefined;
}

