import { describe, expect, it } from "bun:test";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { RestaurantGame } from "./restaurant-game.js";
import { applyArenaReplayInput, replayArenaTrace } from "./replay.js";
import {
  ARENA_ENV_VERSION,
  captureArenaTrace,
  computeStateHash,
  exportTraceJson,
  exportTraceJsonl,
  parseTraceJsonl,
  validateArenaTraceV3,
  type RestaurantArenaTraceV3,
  type TraceV3Event,
} from "./trace.js";

const FIXTURE_PATH = join(import.meta.dir, "../../../contracts/fixtures/restaurant-arena-trace-v3.json");

/** The benchmark shift: open, run to the allergy incident, correct, play out. */
function playFixtureShift(): RestaurantGame {
  const game = new RestaurantGame(218220, "dinner-rush");
  game.step("sim_start");
  for (let i = 0; i < 10; i++) game.step("tick");
  game.step("verify_substitution");
  for (let i = 0; i < 14; i++) game.step("tick");
  return game;
}

function loadFixture(): RestaurantArenaTraceV3 {
  return JSON.parse(readFileSync(FIXTURE_PATH, "utf8")) as RestaurantArenaTraceV3;
}

/** A fresh copy, so one case's tampering cannot leak into the next. */
function tamper(mutate: (trace: RestaurantArenaTraceV3) => void): RestaurantArenaTraceV3 {
  const trace = loadFixture();
  mutate(trace);
  return trace;
}

describe("captureTrace / captureArenaTrace", () => {
  it("captures tick-0 state, the event journal and the replay inputs from a finished shift", () => {
    const game = playFixtureShift();
    const trace = game.captureTrace({ runKind: "benchmark" });

    expect(trace.version).toBe("restaurant-arena-trace/v3");
    expect(trace.contractVersion).toBe("restaurant-arena/v1");
    expect(trace.runKind).toBe("benchmark");
    expect(trace.envVersion).toBe(ARENA_ENV_VERSION);
    expect(trace.seed).toBe(218220);
    expect(trace.deletion).toEqual({ requestId: null, status: "retained" });
    expect(trace.initialState).toEqual(game.getInitialState());
    expect(trace.initialState.episode).toMatchObject({ tick: 0, phase: "active" });
    expect(trace.events).toEqual(game.getRecordedEvents());
    expect(trace.replay).toEqual(game.getReplayRecord());
    expect(trace.replay.inputs.length).toBe(26);
    expect(validateArenaTraceV3(trace)).toEqual({ valid: true, errors: [] });
  });

  it("records the whole terminal record getTerminalStatus returns, not just the status", () => {
    const finished = playFixtureShift().captureTrace({ runKind: "benchmark" });
    expect(finished.terminal).toEqual({ status: "completed", tick: 24, reason: "episode_complete" });

    const abandoned = new RestaurantGame(218220, "dinner-rush");
    abandoned.step("sim_start");
    abandoned.step("tick");
    abandoned.markAbandoned("user_quit");
    expect(abandoned.captureTrace({ runKind: "live" }).terminal).toEqual({
      status: "abandoned",
      tick: 1,
      reason: "user_quit",
    });
  });

  it("is the same capture through the instance method and the standalone helper", () => {
    const game = playFixtureShift();
    const options = { runKind: "benchmark", startTime: "2026-09-05T18:00:00.000Z" } as const;
    expect(game.captureTrace(options)).toEqual(captureArenaTrace(game, options));
  });

  it("refuses to capture without a runKind, because live and benchmark runs must stay apart", () => {
    const game = new RestaurantGame(218220);
    expect(() => game.captureTrace({} as never)).toThrow(/runKind/);
    expect(() => captureArenaTrace(game, { runKind: "demo" } as never)).toThrow(/runKind/);
  });

  it("honours episodeId, sessionId, envVersion and deletion overrides", () => {
    const trace = playFixtureShift().captureTrace({
      runKind: "synthetic",
      episodeId: "synthetic-218220",
      sessionId: "sess-abc123",
      envVersion: "9.9.9",
      deletion: { status: "requested", requestId: "del-1" },
    });
    expect(trace.episodeId).toBe("synthetic-218220");
    expect(trace.sessionId).toBe("sess-abc123");
    expect(trace.envVersion).toBe("9.9.9");
    expect(trace.deletion).toEqual({ requestId: "del-1", status: "requested" });
    expect(validateArenaTraceV3(trace).valid).toBe(true);
  });

  it("leaves sessionId off entirely when the caller has none to quote", () => {
    const trace = playFixtureShift().captureTrace({ runKind: "live" });
    expect("sessionId" in trace).toBe(false);
    expect(validateArenaTraceV3(trace).valid).toBe(true);
  });

  it("re-stamps the journal onto a supplied tick-0 clock, three seconds to the tick", () => {
    const trace = playFixtureShift().captureTrace({
      runKind: "benchmark",
      startTime: "2026-09-05T18:00:00.000Z",
    });
    for (const event of trace.events) {
      expect(event.timestamp).toBe(new Date(Date.parse("2026-09-05T18:00:00.000Z") + event.tick * 3000).toISOString());
    }
    expect(trace.events[0]!.timestamp).toBe("2026-09-05T18:00:00.000Z");
  });

  it("replaces the journal wholesale when events are passed", () => {
    const only: TraceV3Event[] = [
      {
        tick: 0,
        kind: "observation",
        timestamp: "2026-09-05T18:00:00.000Z",
        stateHash: computeStateHash({ hand: "written" }),
        actorId: "system",
      },
    ];
    const trace = playFixtureShift().captureTrace({ runKind: "synthetic", events: only });
    expect(trace.events).toEqual(only);
  });

  it("merges additionalEvents into the journal in tick order, stamped with the round the tick falls in", () => {
    const game = playFixtureShift();
    const note: TraceV3Event = {
      tick: 7,
      kind: "message",
      timestamp: "2026-09-05T18:00:21.000Z",
      stateHash: computeStateHash({ note: "out of band" }),
      actorId: "player",
      text: "Called the shelf tech.",
    };
    const trace = game.captureTrace({ runKind: "live", additionalEvents: [note] });

    expect(trace.events.length).toBe(game.getRecordedEvents().length + 1);
    // Round r covers ticks 2r-1 and 2r, so tick 7 is round 4.
    expect(trace.events.filter((event) => event.text === "Called the shelf tech.")).toEqual([{ ...note, round: 4 }]);
    expect(trace.events.map((event) => event.tick)).toEqual([...trace.events.map((event) => event.tick)].sort((a, b) => a - b));
    // Ties keep the run's own account first; the note annotates it.
    const ticks7 = trace.events.filter((event) => event.tick === 7);
    expect(ticks7.at(-1)!.text).toBe("Called the shelf tech.");
    expect(validateArenaTraceV3(trace).valid).toBe(true);
  });

  it("stamps tick 0 as round 1 and corrects a round the caller got wrong", () => {
    const trace = playFixtureShift().captureTrace({
      runKind: "live",
      additionalEvents: [
        { tick: 0, kind: "message", timestamp: "2026-09-05T18:00:00.000Z", stateHash: computeStateHash({ a: 1 }), text: "opening" },
        { tick: 15, round: 99, kind: "message", timestamp: "2026-09-05T18:00:45.000Z", stateHash: computeStateHash({ b: 2 }), text: "shelf" },
      ],
    });
    expect(trace.events.find((event) => event.text === "opening")!.round).toBe(1);
    expect(trace.events.find((event) => event.text === "shelf")!.round).toBe(8);
  });
});

describe("exportTraceJson / exportTraceJsonl", () => {
  it("writes the fixture byte for byte from a fresh capture of the same shift", () => {
    const trace = playFixtureShift().captureTrace({
      runKind: "benchmark",
      episodeId: "dinner-rush-benchmark-218220",
      startTime: "2026-09-05T18:00:00.000Z",
    });
    expect(exportTraceJson(trace)).toBe(readFileSync(FIXTURE_PATH, "utf8"));
  });

  it("spells float fields with a decimal point so the backend reads them as floats", () => {
    const json = exportTraceJson(loadFixture());
    expect(json).toContain('"cash": 0.0');
    expect(json).toContain('"reading": 62.0');
    expect(json).toContain('"completed": 0');
  });

  it("streams a header line plus one line per event, and round-trips back", () => {
    const trace = loadFixture();
    const lines = exportTraceJsonl(trace).trim().split("\n");

    expect(lines.length).toBe(trace.events.length + 1);
    const header = JSON.parse(lines[0]!) as Record<string, unknown>;
    expect(header.events).toBeUndefined();
    expect(header).toMatchObject({ version: trace.version, episodeId: trace.episodeId, replay: trace.replay });
    for (const line of lines.slice(1)) {
      expect(JSON.parse(line).stateHash).toMatch(/^sha256:[0-9a-f]{64}$/);
    }
    expect(parseTraceJsonl(exportTraceJsonl(trace))).toEqual(trace);
  });
});

describe("validateArenaTraceV3", () => {
  it("accepts the benchmark fixture and every field the schema requires", () => {
    const fixture = loadFixture();
    expect(validateArenaTraceV3(fixture)).toEqual({ valid: true, errors: [] });
    const schema = JSON.parse(
      readFileSync(join(import.meta.dir, "../../../contracts/restaurant-arena-trace-v3.schema.json"), "utf8"),
    ) as { required: string[] };
    for (const field of schema.required) {
      expect(validateArenaTraceV3(tamper((trace) => delete (trace as Record<string, unknown>)[field])).errors).toContain(
        `${field}: is required`,
      );
    }
  });

  it("accepts a historical export that still names the legacy expediter roster", () => {
    const legacy = tamper((trace) => {
      trace.initialState.workers = (trace.initialState.workers as Record<string, unknown>[]).map((worker) =>
        worker.role === "supply_lead" ? { ...worker, id: "worker-expediter", role: "expediter" } : worker,
      );
    });
    expect(validateArenaTraceV3(legacy)).toEqual({ valid: true, errors: [] });
  });

  it("rejects a record that is not an object at all", () => {
    for (const value of [null, undefined, 7, "trace", []]) {
      expect(validateArenaTraceV3(value)).toEqual({ valid: false, errors: ["record: expected an object"] });
    }
  });

  it("names the offending path, field by field", () => {
    const cases: [string, (trace: RestaurantArenaTraceV3) => void, string][] = [
      ["version", (t) => ((t as { version: string }).version = "restaurant-arena-trace/v2"), 'version: expected "restaurant-arena-trace/v3"'],
      ["episodeId", (t) => (t.episodeId = "not a valid id!"), "episodeId: expected an arena id"],
      ["sessionId", (t) => (t.sessionId = ""), "sessionId: expected an arena id"],
      ["seed", (t) => (t.seed = -1), "seed: expected an integer >= 0"],
      ["envVersion", (t) => (t.envVersion = ""), "envVersion: expected at least 1 character(s)"],
      ["contractVersion", (t) => ((t as { contractVersion: string }).contractVersion = "x"), 'contractVersion: expected "restaurant-arena/v1"'],
      ["runKind", (t) => ((t as { runKind: string }).runKind = "demo"), "runKind: expected one of live, synthetic, benchmark"],
      ["unknown field", (t) => ((t as Record<string, unknown>).extra = 1), "extra: is not a known field"],
      ["initialState.version", (t) => (t.initialState.version = "restaurant-arena/v2"), 'initialState.version: expected "restaurant-arena/v1"'],
      ["initialState.reputation", (t) => (t.initialState.reputation = 200), "initialState.reputation: expected a number <= 100"],
      ["initialState.workers[].load", (t) => ((t.initialState.workers as { load: number }[])[0]!.load = 2), "initialState.workers[0].load: expected a number <= 1"],
      ["initialState.inventory", (t) => ((t.initialState.inventory as Record<string, number>).pasta = -1), "initialState.inventory.pasta: expected an integer >= 0"],
      ["events[].timestamp", (t) => (t.events[0]!.timestamp = "yesterday"), "events[0].timestamp: expected an RFC 3339 date-time"],
      ["events[].kind", (t) => ((t.events[0] as { kind: string }).kind = "vibes"), "events[0].kind: expected one of observation"],
      ["events[].stateHash", (t) => (t.events[0]!.stateHash = "sha256:nope"), "events[0].stateHash: expected a sha256: hash"],
      ["events[].round", (t) => (t.events[0]!.round = 0), "events[0].round: expected an integer >= 1"],
      ["events[].role", (t) => ((t.events[1] as { role: string }).role = "sommelier"), "events[1].role: expected one of host"],
      ["events[] unknown field", (t) => ((t.events[0] as Record<string, unknown>).nope = 1), "events[0].nope: is not a known field"],
      ["toolResult without error", (t) => (t.events[1]!.toolResult = { ok: false }), "events[1].toolResult.error: is required when ok is false"],
      ["toolResult error with ok", (t) => (t.events[1]!.toolResult = { ok: true, error: { code: "x", message: "y" } }), "events[1].toolResult.ok: expected false"],
      ["deletion.status", (t) => ((t.deletion as { status: string }).status = "gone"), "deletion.status: expected one of retained, requested, deleted"],
      ["terminal.status", (t) => ((t.terminal as { status: string }).status = "paused"), "terminal.status: expected one of active, completed, abandoned"],
      ["terminal.tick", (t) => (t.terminal.tick = -1), "terminal.tick: expected an integer >= 0"],
      ["terminal.reason", (t) => ((t.terminal as { reason: unknown }).reason = 7), "terminal.reason: expected a string or null"],
      ["replay.variation", (t) => (t.replay.variation = "brunch"), "replay.variation: expected one of tutorial-shift"],
      ["replay.finalStateHash", (t) => (t.replay.finalStateHash = "deadbeef"), "replay.finalStateHash: expected a sha256: hash"],
      ["replay.inputs[].kind", (t) => ((t.replay.inputs[0] as { kind: string }).kind = "teleport"), "replay.inputs[0].kind: expected one of step, time, envelope, controllers"],
      ["replay.inputs[].action", (t) => delete (t.replay.inputs[0] as Record<string, unknown>).action, "replay.inputs[0].action: is required"],
      ["replay.inputs[].stateHash", (t) => (t.replay.inputs[0]!.stateHash = "sha256:zz"), "replay.inputs[0].stateHash: expected a sha256: hash"],
    ];

    for (const [label, mutate, expected] of cases) {
      const result = validateArenaTraceV3(tamper(mutate));
      expect(result.valid, label).toBe(false);
      expect(result.errors.join("\n"), label).toContain(expected);
    }
  });
});

describe("replayArenaTrace", () => {
  it("returns the rebuilt live game, not a summary", () => {
    const trace = loadFixture();
    const game = replayArenaTrace(trace);

    expect(game).toBeInstanceOf(RestaurantGame);
    expect(game.getTerminalStatus()).toEqual(trace.terminal);
    expect(computeStateHash(game.checkpointState())).toBe(trace.replay.finalStateHash);
    expect(game.state().episode.tick).toBe(24);
    expect(game.isOver()).toBe(true);
    expect(replayArenaTrace(trace).state()).toEqual(game.state());
  });

  it("re-derives the same event journal the trace recorded", () => {
    const trace = loadFixture();
    const withoutTimestamps = (events: TraceV3Event[]) => events.map(({ timestamp, ...rest }) => rest);
    expect(withoutTimestamps(replayArenaTrace(trace).getRecordedEvents())).toEqual(withoutTimestamps(trace.events));
  });

  it("replays a historical trace naming the legacy expediter roster to the identical terminal record", () => {
    const legacy = tamper((trace) => {
      const workers = (trace.initialState.workers as Record<string, unknown>[]).map((worker) =>
        worker.role === "supply_lead" ? { ...worker, id: "worker-expediter", role: "expediter" } : worker,
      );
      // Historical exports also listed the roster in a different order.
      trace.initialState.workers = [workers[2], workers[3], workers[0], workers[1]];
    });
    const game = replayArenaTrace(legacy);
    expect(game.getTerminalStatus()).toEqual(legacy.terminal);
    expect(computeStateHash(game.checkpointState())).toBe(legacy.replay.finalStateHash);
    expect(game.state().workers.map((worker) => worker.role)).toContain("supply_lead");
  });

  it("rejects an initialState altered in any field, including ones with no schema rule of their own", () => {
    for (const mutate of [
      (t: RestaurantArenaTraceV3) => ((t.initialState.outcomes as { cash: number }).cash = 5),
      (t: RestaurantArenaTraceV3) => (t.initialState.reputation = 51),
      (t: RestaurantArenaTraceV3) => ((t.initialState.inventory as Record<string, number>).pasta = 9),
      (t: RestaurantArenaTraceV3) => ((t.initialState.workers as { location: string }[])[0]!.location = "kitchen"),
    ]) {
      const altered = tamper(mutate);
      // Still a perfectly well-formed record — that is the point.
      expect(validateArenaTraceV3(altered).valid).toBe(true);
      expect(() => replayArenaTrace(altered)).toThrow(/initial state mismatch/);
    }
  });

  it("rejects a tampered or truncated checkpoint hash", () => {
    expect(() => replayArenaTrace(tamper((t) => (t.replay.inputs[3]!.stateHash = `sha256:${"0".repeat(64)}`)))).toThrow(
      /checkpoint hash mismatch/,
    );
    expect(() =>
      replayArenaTrace(tamper((t) => (t.replay.inputs[3]!.restaurantStateHash = `sha256:${"0".repeat(64)}`))),
    ).toThrow(/restaurant state hash mismatch/);
    expect(() => replayArenaTrace(tamper((t) => t.replay.inputs.splice(5, 1)))).toThrow();
    expect(() => replayArenaTrace(tamper((t) => (t.replay.finalStateHash = `sha256:${"1".repeat(64)}`)))).toThrow(
      /final state hash mismatch/,
    );
    expect(() =>
      replayArenaTrace(tamper((t) => (t.replay.finalRestaurantStateHash = `sha256:${"1".repeat(64)}`))),
    ).toThrow(/final restaurant state hash mismatch/);
  });

  it("rejects every part of a disagreeing terminal record, not just the status", () => {
    for (const mutate of [
      (t: RestaurantArenaTraceV3) => ((t.terminal as { status: "abandoned" }).status = "abandoned"),
      (t: RestaurantArenaTraceV3) => (t.terminal.tick = 23),
      (t: RestaurantArenaTraceV3) => (t.terminal.reason = "user_quit"),
      (t: RestaurantArenaTraceV3) => (t.terminal.reason = null),
    ]) {
      expect(() => replayArenaTrace(tamper(mutate))).toThrow(/terminal mismatch/);
    }
  });

  it("applies one recorded input at a time, checking the checkpoint it lands on", () => {
    const trace = loadFixture();
    const game = new RestaurantGame(trace.seed, trace.replay.variation);
    trace.replay.inputs.forEach((input, index) => applyArenaReplayInput(game, input, index));
    expect(computeStateHash(game.checkpointState())).toBe(trace.replay.finalStateHash);

    const drifted = new RestaurantGame(trace.seed, trace.replay.variation);
    expect(() => applyArenaReplayInput(drifted, { ...trace.replay.inputs[1]!, tick: 9 }, 1)).toThrow(/recorded tick 9/);
  });
});

