import { describe, expect, test } from "bun:test";
import { spawnSync } from "node:child_process";
import { mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import {
  exportTraceJson,
  exportTraceJsonl,
  type RestaurantArenaTraceV3,
} from "../src/games/restaurant-arena/trace.js";

const ROOT = join(import.meta.dir, "..");
const FIXTURE = join(ROOT, "contracts/fixtures/restaurant-arena-trace-v3.json");
const EXPORT_CLI = join(ROOT, "scripts/export-arena-trace.ts");
const REPLAY_CLI = join(ROOT, "scripts/replay-arena-trace.ts");

function run(script: string, args: string[]) {
  const result = spawnSync(process.execPath, [script, ...args], { cwd: ROOT, encoding: "utf8" });
  return { code: result.status, stdout: result.stdout ?? "", stderr: result.stderr ?? "" };
}

function fixture(): RestaurantArenaTraceV3 {
  return JSON.parse(readFileSync(FIXTURE, "utf8")) as RestaurantArenaTraceV3;
}

/** Write a tampered copy of the fixture into a scratch directory. */
function withTrace(
  name: string,
  mutate: (trace: RestaurantArenaTraceV3) => void,
  format: "json" | "jsonl" = "json",
): { path: string; cleanup: () => void } {
  const dir = mkdtempSync(join(tmpdir(), "arena-trace-"));
  const trace = fixture();
  mutate(trace);
  const path = join(dir, name);
  writeFileSync(path, format === "jsonl" ? exportTraceJsonl(trace) : exportTraceJson(trace));
  return { path, cleanup: () => rmSync(dir, { recursive: true, force: true }) };
}

describe("scripts/export-arena-trace.ts", () => {
  test("--check reports the committed fixture is current", () => {
