function run(script: string, args: string[]) {
  const result = spawnSync(process.execPath, [script, ...args], { cwd: ROOT, encoding: "utf8" });
  return { code: result.status, stdout: result.stdout ?? "", stderr: result.stderr ?? "" };
}

function fixture(): RestaurantArenaTraceV3 {
  return JSON.parse(readFileSync(FIXTURE, "utf8")) as RestaurantArenaTraceV3;
}

/** Write a tampered copy of the fixture into a scratch directory. */
function withTrace(
  name: string,
  mutate: (trace: RestaurantArenaTraceV3) => void,
  format: "json" | "jsonl" = "json",
): { path: string; cleanup: () => void } {
  const dir = mkdtempSync(join(tmpdir(), "arena-trace-"));
  const trace = fixture();
  mutate(trace);
  const path = join(dir, name);
  writeFileSync(path, format === "jsonl" ? exportTraceJsonl(trace) : exportTraceJson(trace));
  return { path, cleanup: () => rmSync(dir, { recursive: true, force: true }) };
