1	#!/usr/bin/env bun
2	/**
3	 * Replay a trace file from disk and say whether the engine agrees with it.
4	 *
5	 *   bun scripts/replay-arena-trace.ts <path-to-trace.json-or-.jsonl>
6	 *
7	 * Both export shapes are accepted: the pretty JSON document from
8	 * `exportTraceJson` and the header-plus-events stream from
9	 * `exportTraceJsonl`. The record goes through `validateArenaTraceV3` and then
10	 * `replayArenaTrace`, which rebuilds the game from the seed and checks its own
11	 * checkpoints against every hash and the terminal record the file claims.
12	 *
13	 * `Native replay passed` is printed only when all of that holds. A tampered,
14	 * truncated or malformed file exits non-zero without printing it.
15	 */
16	
17	import { readFileSync } from "node:fs";
18	import type { RestaurantGame } from "../src/games/restaurant-arena/restaurant-game.js";
19	import { replayArenaTrace } from "../src/games/restaurant-arena/replay.js";
20	import {
21	  canonicalJson,
22	  parseTraceJsonl,
23	  validateArenaTraceV3,
24	  type RestaurantArenaTraceV3,
25	  type TraceV3Event,
26	} from "../src/games/restaurant-arena/trace.js";
27	
28	/**
29	 * Read either export shape. The extension is a hint, not the authority: a
30	 * whole-file JSON parse settles it, because a JSONL file's first line parses
31	 * on its own but the file as a whole does not.
32	 */
33	export function loadTraceFile(path: string): RestaurantArenaTraceV3 {
34	  const text = readFileSync(path, "utf8");
35	  try {
36	    return JSON.parse(text) as RestaurantArenaTraceV3;
37	  } catch {
38	    return parseTraceJsonl(text);
39	  }
40	}
41	
42	/** Legacy names a historical export may still use for the supply lead. */
43	const LEGACY_NAMES: Readonly<Record<string, string>> = {
44	  expediter: "supply_lead",
45	  "worker-expediter": "worker-supply_lead",
46	};
47	
48	/**
49	 * One event, reduced to what replay can reproduce: wall-clock timestamps come
50	 * from the machine that played the shift, and the legacy role names map
51	 * forward, but everything else — tick, round, kind, actor, payload, hash —
52	 * has to come back the same.
53	 */
54	function eventFingerprint(event: TraceV3Event): string {
55	  const { timestamp, ...rest } = event as TraceV3Event & Record<string, unknown>;
56	  const mapped: Record<string, unknown> = { ...rest };
57	  for (const key of ["actorId", "role", "targetRole"] as const) {
58	    const value = mapped[key];
59	    if (typeof value === "string" && LEGACY_NAMES[value]) mapped[key] = LEGACY_NAMES[value];
60	  }
61	  return canonicalJson(mapped);
62	}
63	
64	/**
65	 * The recorded journal has to account for every event the engine itself
66	 * re-derives, in order. Hashes alone cannot catch this: a JSONL export with
67	 * event lines lopped off still replays its inputs perfectly, and the missing
68	 * events are exactly the evidence the file exists to carry. Events the record
69	 * has and replay does not are left alone — a capture may legitimately merge
70	 * caller-supplied notes into the journal.
71	 */
72	function missingJournalEvents(trace: RestaurantArenaTraceV3, game: RestaurantGame): string | undefined {
73	  const recorded = trace.events.map(eventFingerprint);
74	  const replayed = game.getRecordedEvents();
75	  let cursor = 0;
76	  for (const [index, event] of replayed.entries()) {
77	    const found = recorded.indexOf(eventFingerprint(event), cursor);
78	    if (found === -1) {
79	      return `recorded journal does not account for replay event ${index} (${event.kind} at tick ${event.tick}); the journal is truncated or altered`;
80	    }
81	    cursor = found + 1;
82	  }
83	  return undefined;
84	}
85	
86	function main(argv: readonly string[]): number {
87	  const path = argv.find((arg) => !arg.startsWith("-"));
88	  if (!path) {
89	    console.error("usage: bun scripts/replay-arena-trace.ts <path-to-trace.json-or-.jsonl>");
90	    return 1;
91	  }
92	
93	  let trace: RestaurantArenaTraceV3;
94	  try {
95	    trace = loadTraceFile(path);
96	  } catch (err) {
97	    console.error(`Could not read a trace from ${path}: ${err instanceof Error ? err.message : String(err)}`);
98	    return 1;
99	  }
100	
101	  const validation = validateArenaTraceV3(trace);
102	  if (!validation.valid) {
103	    console.error(`${path} is not a valid restaurant-arena-trace-v3 record:`);
104	    for (const error of validation.errors) console.error(`  ${error}`);
105	    return 1;
106	  }
107	
108	  let game;
109	  try {
110	    game = replayArenaTrace(trace);
111	  } catch (err) {
112	    console.error(`Native replay failed for ${path}: ${err instanceof Error ? err.message : String(err)}`);
113	    return 1;
114	  }
115	
116	  const gap = missingJournalEvents(trace, game);
117	  if (gap) {
118	    console.error(`Native replay failed for ${path}: ${gap}`);
119	    return 1;
120	  }
121	
122	  const terminal = game.getTerminalStatus();
123	  console.log(
124	    `Native replay passed: ${trace.episodeId} (${trace.runKind}, seed ${trace.seed}, ${trace.replay.variation}) — ` +
125	      `${trace.replay.inputs.length} inputs, ${trace.events.length} events, ` +
126	      `terminal ${terminal.status} at tick ${terminal.tick}${terminal.reason ? ` (${terminal.reason})` : ""}`,
127	  );
128	  return 0;
129	}
130	
131	if (import.meta.main) {
132	  try {
133	    process.exit(main(process.argv.slice(2)));
134	  } catch (err) {
135	    console.error(err instanceof Error ? err.message : String(err));
136	    process.exit(1);
137	  }
138	}
