const LEGACY_NAMES: Readonly<Record<string, string>> = {
  expediter: "supply_lead",
  "worker-expediter": "worker-supply_lead",
};

/**
 * One event, reduced to what replay can reproduce: wall-clock timestamps come
 * from the machine that played the shift, and the legacy role names map
 * forward, but everything else — tick, round, kind, actor, payload, hash —
 * has to come back the same.
 */
function eventFingerprint(event: TraceV3Event): string {
  const { timestamp, ...rest } = event as TraceV3Event & Record<string, unknown>;
  const mapped: Record<string, unknown> = { ...rest };
  for (const key of ["actorId", "role", "targetRole"] as const) {
    const value = mapped[key];
    if (typeof value === "string" && LEGACY_NAMES[value]) mapped[key] = LEGACY_NAMES[value];
