 * re-derives, in order. Hashes alone cannot catch this: a JSONL export with
 * event lines lopped off still replays its inputs perfectly, and the missing
 * events are exactly the evidence the file exists to carry. Events the record
 * has and replay does not are left alone — a capture may legitimately merge
 * caller-supplied notes into the journal.
 */
function missingJournalEvents(trace: RestaurantArenaTraceV3, game: RestaurantGame): string | undefined {
  const recorded = trace.events.map(eventFingerprint);
  const replayed = game.getRecordedEvents();
  let cursor = 0;
  for (const [index, event] of replayed.entries()) {
    const found = recorded.indexOf(eventFingerprint(event), cursor);
    if (found === -1) {
      return `recorded journal does not account for replay event ${index} (${event.kind} at tick ${event.tick}); the journal is truncated or altered`;
    }
    cursor = found + 1;
  }
  return undefined;
}

